-- Ragdoll Soccer v0.7.3 (bundled by build.py)
local __env = getgenv and getgenv() or _G
__env.RSVersion = "0.7.3"
local __mods, __cache = {}, {}
local function __import(n)
	if __cache[n] == nil then __cache[n] = __mods[n]() end
	return __cache[n]
end

__mods["lib/logo"] = function()
-- The Scrdsx logo (192x192 PNG, embedded). Logo.Get() writes it to the workspace once and returns an asset id for ImageLabels (nil when the executor cannot).
local Logo = {}
local DATA = ""
local path = "RagdollSoccer/logo_v2.png"
local cached

local function decode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
	local out, buf, bits = {}, 0, 0
	for i = 1, #s do
		local v = map[s:sub(i, i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local byte = math.floor(buf / 2 ^ bits)
				out[#out + 1] = string.char(byte)
				buf = buf - byte * 2 ^ bits
			end
		end
	end
	return table.concat(out)
end

function Logo.Get()
	if cached ~= nil then return cached or nil end
	cached = false
	pcall(function()
		if not (writefile and getcustomasset) then return end
		pcall(function() if makefolder then makefolder("RagdollSoccer") end end)
		if not (isfile and isfile(path)) then writefile(path, decode(DATA)) end
		cached = getcustomasset(path)
	end)
	return cached or nil
end

-- puts the logo (or a blue "S" badge when images are not available) into parent
function Logo.Make(parent, size, pos)
	local id = Logo.Get()
	local el
	if id then
		el = Instance.new("ImageLabel")
		el.BackgroundTransparency = 1
		el.Image = id
		el.ScaleType = Enum.ScaleType.Fit
	else
		el = Instance.new("Frame")
		el.BackgroundColor3 = Color3.fromRGB(64, 132, 255)
		el.BorderSizePixel = 0
		local cr = Instance.new("UICorner"); cr.CornerRadius = UDim.new(0.26, 0); cr.Parent = el
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1; t.Size = UDim2.fromScale(1, 1); t.Text = "S"; t.TextColor3 = Color3.new(1, 1, 1)
		t.Font = Enum.Font.BuilderSansBold; t.TextSize = math.floor(size * 0.6); t.Parent = el
	end
	el.Size = UDim2.fromOffset(size, size)
	if pos then el.Position = pos end
	el.Parent = parent
	return el
end

return Logo

end

__mods["lib/icons"] = function()
-- Tab icons: a sprite sheet (19 icons, 64x64 px each, white on transparent, embedded) written to the workspace once.
-- Icons.Make(parent, index, size, pos) -> ImageLabel (tint it with ImageColor3), or nil when the executor cannot load images.
-- laid out 10 per row (Roblox shrinks images wider than 1024 px, which garbled the old single-row sheet)
-- 20 sun, 21 grid; 1 car, 2 person, 3 eye, 4 crosshair, 5 pin, 6 coin, 7 bolt, 8 folder, 9 gear, 10 shield, 11 store, 12 bomb, 13 sparkle, 14 hand, 15 bell, 16 map, 17 sliders, 18 flag, 19 signal
local Icons = { Cell = 64, Count = 21, Cols = 10 }
local DATA = ""
local path = "RagdollSoccer/icons_v3.png"
local cached

local function decode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
	local out, buf, bits = {}, 0, 0
	for i = 1, #s do
		local v = map[s:sub(i, i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local byte = math.floor(buf / 2 ^ bits)
				out[#out + 1] = string.char(byte)
				buf = buf - byte * 2 ^ bits
			end
		end
	end
	return table.concat(out)
end

function Icons.Get()
	if cached ~= nil then return cached or nil end
	cached = false
	pcall(function()
		if not (writefile and getcustomasset) then return end
		pcall(function() if makefolder then makefolder("RagdollSoccer") end end)
		if not (isfile and isfile(path)) then writefile(path, decode(DATA)) end
		cached = getcustomasset(path)
	end)
	return cached or nil
end

function Icons.Make(parent, index, size, pos)
	local id = Icons.Get()
	if not id or not index then return nil end
	local el = Instance.new("ImageLabel")
	el.BackgroundTransparency = 1
	el.Image = id
	el.ImageRectSize = Vector2.new(Icons.Cell, Icons.Cell)
	el.ImageRectOffset = Vector2.new(((index - 1) % Icons.Cols) * Icons.Cell, math.floor((index - 1) / Icons.Cols) * Icons.Cell)
	el.Size = UDim2.fromOffset(size, size)
	if pos then el.Position = pos end
	el.Parent = parent
	return el
end

return Icons

end

__mods["lib/sfx"] = function()
-- UI sounds: short soft tones (generated by tools/gen_sfx.py, embedded ogg). Written to the workspace once, played through getcustomasset.
-- Sfx.Play(name, volume?) with name = click, hover, on, off, tab, notify, warn, open, close, success. Silent (no errors) when the executor cannot load audio.
local SoundService = game:GetService("SoundService")
local Debris = game:GetService("Debris")

local Sfx = { Enabled = true, Volume = 0.55, Keys = false, KeyVolume = 0.5 }
local ids, data = {}, {}

data.click = ""
data.hover = ""
data.on = ""
data.off = ""
data.tab = ""
data.notify = ""
data.warn = ""
data.open = ""
data.close = ""
data.success = ""

data.key1 = ""
data.key2 = ""
data.key3 = ""
data.key4 = ""
data.keyspace = ""

local function decode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
	local out, buf, bits = {}, 0, 0
	for i = 1, #s do
		local v = map[s:sub(i, i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local byte = math.floor(buf / 2 ^ bits)
				out[#out + 1] = string.char(byte)
				buf = buf - byte * 2 ^ bits
			end
		end
	end
	return table.concat(out)
end

local canLoad = writefile and getcustomasset and isfile
local function idFor(name)
	if ids[name] ~= nil then return ids[name] or nil end
	ids[name] = false
	if not canLoad or not data[name] then return nil end
	pcall(function()
		pcall(function() if makefolder then makefolder("RagdollSoccer") end end)
		local path = "RagdollSoccer/sfx_v1_" .. name .. ".ogg"
		if not isfile(path) then writefile(path, decode(data[name])) end
		ids[name] = getcustomasset(path)
	end)
	return ids[name] or nil
end

local last = {}
function Sfx.Play(name, vol, speed)
	if not Sfx.Enabled then return end
	local now = os.clock()
	if last[name] and now - last[name] < 0.04 then return end -- never stack the same sound
	last[name] = now
	local id = idFor(name)
	if not id then return end
	pcall(function()
		local s = Instance.new("Sound")
		s.SoundId = id
		s.Volume = (vol or 1) * Sfx.Volume
		s.PlaybackSpeed = speed or 1
		s.RollOffMaxDistance = 0
		s.Parent = SoundService
		s:Play()
		Debris:AddItem(s, 3)
	end)
end

-- creamy keyboard sound: a random one of four, slightly different pitch each press, a deeper one for space
local KEYSEQ = { "key1", "key2", "key3", "key4" }
local keyN = 0
function Sfx.Key(isSpace)
	if not Sfx.Keys then return end
	keyN = keyN + 1
	local name = isSpace and "keyspace" or KEYSEQ[(keyN + math.random(0, 2)) % #KEYSEQ + 1]
	local id = idFor(name)
	if not id then return end
	pcall(function()
		local s = Instance.new("Sound")
		s.SoundId = id
		s.Volume = Sfx.KeyVolume
		s.PlaybackSpeed = 0.94 + math.random() * 0.14
		s.RollOffMaxDistance = 0
		s.Parent = SoundService
		s:Play()
		Debris:AddItem(s, 1)
	end)
end

-- prepare every file in the background so the first click is not delayed
function Sfx.Preload()
	task.spawn(function()
		for name in pairs(data) do
			pcall(idFor, name)
			task.wait()
		end
	end)
end

return Sfx
end

__mods["lib/ui"] = function()
-- Scrdsx UI library v3: flat, quiet and fast (modelled on the Athena executor's own look). No gradients, no glow, no heavy effects.
-- Window = sidebar (brand, grouped tabs, you) + page (title, search, close). Modules are slim rows (name, setting count, gear, switch);
-- the gear slides a plain settings drawer in from the right. Plain Frames only (a CanvasGroup under UIScale makes text soft).
-- Every themed colour is a binding (win.binds) so a theme change recolours everything, including elements that are mid-state.
local TweenService = game:GetService("TweenService")
local UIS = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local Players = game:GetService("Players")
local Lighting = game:GetService("Lighting")
local Logo = __import("lib/logo")
local Icons = __import("lib/icons")
local Sfx = __import("lib/sfx")

local function pickFont(n, fb) local ok, f = pcall(function() return Enum.Font[n] end); return (ok and f) or fb end
local T = {
	bg = Color3.fromRGB(19, 19, 21),
	panel = Color3.fromRGB(24, 24, 27),
	elem = Color3.fromRGB(33, 33, 37),
	hover = Color3.fromRGB(41, 41, 46),
	stroke = Color3.fromRGB(43, 43, 48),
	text = Color3.fromRGB(240, 240, 245),
	sub = Color3.fromRGB(145, 145, 155),
	accent = Color3.fromRGB(238, 238, 244),
	accentDim = Color3.fromRGB(46, 46, 52),
	off = Color3.fromRGB(70, 70, 77),
	chip = Color3.fromRGB(238, 238, 244),
	gradA = Color3.fromRGB(238, 238, 244),
	gradB = Color3.fromRGB(238, 238, 244),
	strokeOn = Color3.fromRGB(88, 88, 98),
	font = pickFont("BuilderSansMedium", Enum.Font.Gotham),
	bold = pickFont("BuilderSansBold", Enum.Font.GothamBold),
	semi = pickFont("BuilderSansBold", Enum.Font.GothamBold),
}

local SIDE_W, TOP_H = 204, 74
local DRAWER_W = 348
local WHITE = Color3.new(1, 1, 1)

local function tween(o, t, p, style, dir)
	local tw = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), p)
	tw:Play()
	return tw
end

local function new(class, props, children)
	local i = Instance.new(class)
	for k, v in pairs(props or {}) do i[k] = v end
	for _, c in ipairs(children or {}) do c.Parent = i end
	return i
end
local function corner(r) return new("UICorner", { CornerRadius = UDim.new(0, r) }) end
local function pad(l, r, t, b) return new("UIPadding", { PaddingLeft = UDim.new(0, l or 0), PaddingRight = UDim.new(0, r or l or 0), PaddingTop = UDim.new(0, t or 0), PaddingBottom = UDim.new(0, b or t or 0) }) end

local function guiParent()
	local ok, h = pcall(function() return gethui and gethui() end)
	if ok and h then return h end
	ok, h = pcall(function() return game:GetService("CoreGui") end)
	if ok and h then return h end
	return Players.LocalPlayer:WaitForChild("PlayerGui")
end

local UI = {}
UI.__index = UI

-- bind(win, instance, "Property", "tokenName" | function() return value end): set now, and again whenever the theme changes
local function bind(win, inst, prop, f)
	local fn = type(f) == "string" and function() return T[f] end or f
	inst[prop] = fn()
	win.binds[#win.binds + 1] = { inst, prop, fn }
	return inst
end

local function mkStroke(win, key, transparency)
	local s = new("UIStroke", { Thickness = 1, Transparency = transparency or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
	bind(win, s, "Color", key or "stroke")
	return s
end

local function text(win, str, size, key, font, align)
	local l = new("TextLabel", {
		BackgroundTransparency = 1, Text = str, TextSize = size or 13, Font = font or T.font, TextXAlignment = align or Enum.TextXAlignment.Left,
		TextWrapped = true, TextTruncate = Enum.TextTruncate.None, RichText = false,
	})
	bind(win, l, "TextColor3", key or "text")
	return l
end

function UI.new(opts)
	opts = opts or {}
	local self = setmetatable({ tabs = {}, rows = {}, sections = {}, conns = {}, flags = {}, binds = {}, active = nil, visible = true, baseScale = 1, autoScale = 1, navOrder = 0, blurSize = 0 }, UI)

	local gui = new("ScreenGui", {
		Name = tostring(math.random(1e6, 9e6)), ResetOnSpawn = false, IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 999,
	})
	pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
	gui.Parent = guiParent()
	self.gui = gui

	local holder = new("Frame", { Name = "Root", Size = UDim2.fromOffset(940, 640), AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(.5, .5), BackgroundTransparency = 1, BorderSizePixel = 0, Parent = gui })
	local root = new("Frame", { Name = "Window", Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ClipsDescendants = true, Parent = holder }, { corner(14) })
	bind(self, root, "BackgroundColor3", "bg"); root.BackgroundTransparency = 0.02
	mkStroke(self, "stroke", 0).Parent = root
	self.root = holder
	self.window = root

	pcall(function()
		local b = Instance.new("BlurEffect")
		b.Name = "ScrdsxGlass"; b.Size = 0; b.Parent = Lighting
		self.blur = b
	end)
	self.scale = new("UIScale", { Scale = .94, Parent = holder })
	do
		local cam = workspace.CurrentCamera
		local vh = cam and cam.ViewportSize.Y or 800
		self.autoScale = math.clamp(vh / 860, 1, 1.4)
		self.baseScale = self.autoScale
	end

	-- SIDEBAR ---------------------------------------------------------------------------------------------------------
	local side = new("Frame", { Name = "Side", Size = UDim2.new(0, SIDE_W, 1, 0), BackgroundTransparency = 1, Parent = root })
	local brand = new("Frame", { Size = UDim2.new(1, 0, 0, TOP_H), BackgroundTransparency = 1, Parent = side })
	Logo.Make(brand, 32, UDim2.fromOffset(20, 21))
	local title = text(self, opts.Title or "Window", 15, "text", T.bold); title.Position = UDim2.fromOffset(60, 20); title.Size = UDim2.new(1, -66, 0, 18); title.TextWrapped = false; title.Parent = brand
	local sub = text(self, opts.Subtitle or "", 11, "sub"); sub.Position = UDim2.fromOffset(60, 39); sub.Size = UDim2.new(1, -66, 0, 14); sub.TextWrapped = false; sub.Parent = brand

	local nav = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, TOP_H), Size = UDim2.new(1, 0, 1, -TOP_H - 58), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 0,
		AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), ScrollingDirection = Enum.ScrollingDirection.Y, Parent = side,
	})
	new("UIListLayout", { Padding = UDim.new(0, 1), SortOrder = Enum.SortOrder.LayoutOrder, Parent = nav })
	pad(14, 12, 0, 8).Parent = nav
	self.nav = nav

	local lp = Players.LocalPlayer
	local me = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 14, 1, -14), Size = UDim2.new(1, -26, 0, 40), BackgroundTransparency = 1, Parent = side })
	local av = new("ImageLabel", { Position = UDim2.fromOffset(2, 4), Size = UDim2.fromOffset(32, 32), BorderSizePixel = 0, Image = "", Parent = me }, { corner(16) })
	bind(self, av, "BackgroundColor3", "elem")
	task.spawn(function() pcall(function() av.Image = Players:GetUserThumbnailAsync(lp.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100) end) end)
	local pn = text(self, lp.DisplayName, 12, "text", T.bold); pn.Position = UDim2.fromOffset(44, 4); pn.Size = UDim2.new(1, -46, 0, 16); pn.TextWrapped = false; pn.TextTruncate = Enum.TextTruncate.AtEnd; pn.Parent = me
	local ph = text(self, "Right Shift to hide", 10, "sub"); ph.Position = UDim2.fromOffset(44, 21); ph.Size = UDim2.new(1, -46, 0, 14); ph.TextWrapped = false; ph.Parent = me

	local vline = new("Frame", { Position = UDim2.fromOffset(SIDE_W, 0), Size = UDim2.new(0, 1, 1, 0), BorderSizePixel = 0, Parent = root })
	bind(self, vline, "BackgroundColor3", "stroke")

	-- TOP BAR ---------------------------------------------------------------------------------------------------------
	local top = new("Frame", { Position = UDim2.fromOffset(SIDE_W + 1, 0), Size = UDim2.new(1, -(SIDE_W + 1), 0, TOP_H), BackgroundTransparency = 1, Parent = root })
	self.pageTitle = text(self, "", 22, "text", T.bold); self.pageTitle.Position = UDim2.fromOffset(26, 16); self.pageTitle.Size = UDim2.new(.5, 0, 0, 28); self.pageTitle.TextWrapped = false; self.pageTitle.Parent = top
	self.pageSub = text(self, "", 12, "sub"); self.pageSub.Position = UDim2.fromOffset(27, 44); self.pageSub.Size = UDim2.new(.5, 0, 0, 16); self.pageSub.TextWrapped = false; self.pageSub.Parent = top

	local close = new("TextButton", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -20, 0, 19), Size = UDim2.fromOffset(34, 34), BorderSizePixel = 0, AutoButtonColor = false, Text = "", Parent = top }, { corner(17) })
	bind(self, close, "BackgroundColor3", "elem")
	local cx = text(self, "×", 20, "sub", T.bold, Enum.TextXAlignment.Center); cx.Size = UDim2.fromScale(1, 1); cx.TextWrapped = false; cx.Parent = close
	close.MouseEnter:Connect(function() tween(close, .12, { BackgroundColor3 = T.hover }); tween(cx, .12, { TextColor3 = T.text }) end)
	close.MouseLeave:Connect(function() tween(close, .12, { BackgroundColor3 = T.elem }); tween(cx, .12, { TextColor3 = T.sub }) end)
	close.MouseButton1Click:Connect(function() Sfx.Play("click"); self:SetVisible(false) end)

	local sb = new("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -64, 0, 19), Size = UDim2.fromOffset(190, 34), BorderSizePixel = 0, Parent = top }, { corner(17) })
	bind(self, sb, "BackgroundColor3", "elem")
	local sbStroke = mkStroke(self, "elem", 0); sbStroke.Parent = sb
	local box = new("TextBox", {
		BackgroundTransparency = 1, Size = UDim2.new(1, -50, 1, 0), Position = UDim2.fromOffset(16, 0), Text = "", PlaceholderText = "Search", ClearTextOnFocus = false,
		Font = T.font, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = sb,
	})
	bind(self, box, "TextColor3", "text"); bind(self, box, "PlaceholderColor3", "sub")
	local hint = text(self, "/", 12, "sub", T.bold, Enum.TextXAlignment.Center); hint.AnchorPoint = Vector2.new(1, .5); hint.Position = UDim2.new(1, -14, .5, 0); hint.Size = UDim2.fromOffset(16, 16); hint.TextWrapped = false; hint.Parent = sb
	self.searchBox = box
	box.Focused:Connect(function() tween(sbStroke, .15, { Color = T.strokeOn }); tween(sb, .2, { Size = UDim2.fromOffset(230, 34) }); tween(hint, .15, { TextTransparency = 1 }) end)
	box.FocusLost:Connect(function()
		tween(sbStroke, .15, { Color = T.elem })
		if box.Text == "" then tween(sb, .2, { Size = UDim2.fromOffset(190, 34) }); tween(hint, .15, { TextTransparency = 0 }) end
	end)
	box:GetPropertyChangedSignal("Text"):Connect(function() self:_search(box.Text) end)

	-- drag by the top bar and the brand
	do
		local dragging, start, origin
		local function begin(i, avoid)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
				for _, g in ipairs(avoid or {}) do
					local p, a, z = i.Position, g.AbsolutePosition, g.AbsoluteSize
					if p.X >= a.X and p.X <= a.X + z.X and p.Y >= a.Y and p.Y <= a.Y + z.Y then return end
				end
				dragging, start, origin = true, i.Position, holder.Position
			end
		end
		top.InputBegan:Connect(function(i) begin(i, { sb, close }) end)
		brand.InputBegan:Connect(function(i) begin(i) end)
		table.insert(self.conns, UIS.InputChanged:Connect(function(i)
			if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
				local d = i.Position - start
				holder.Position = UDim2.new(origin.X.Scale, origin.X.Offset + d.X, origin.Y.Scale, origin.Y.Offset + d.Y)
			end
		end))
		table.insert(self.conns, UIS.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
		end))
	end

	-- CONTENT ---------------------------------------------------------------------------------------------------------
	local content = new("ScrollingFrame", {
		Position = UDim2.fromOffset(SIDE_W + 1, TOP_H), Size = UDim2.new(1, -(SIDE_W + 1), 1, -TOP_H), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
		AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Parent = root,
	})
	bind(self, content, "ScrollBarImageColor3", "off")
	new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = content })
	pad(24, 26, 4, 24).Parent = content
	self.content = content

	-- DRAWER (settings of one module) ------------------------------------------------------------------------------
	local drawer = new("Frame", {
		Name = "Drawer", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, DRAWER_W + 30, 0, 10), Size = UDim2.new(0, DRAWER_W, 1, -20), BorderSizePixel = 0, Visible = false, ZIndex = 5, Parent = root,
	}, { corner(12) })
	bind(self, drawer, "BackgroundColor3", "panel")
	mkStroke(self, "stroke", 0).Parent = drawer
	local dtitle = text(self, "", 16, "text", T.bold); dtitle.Position = UDim2.fromOffset(20, 16); dtitle.Size = UDim2.new(1, -70, 0, 20); dtitle.TextWrapped = false; dtitle.TextTruncate = Enum.TextTruncate.AtEnd; dtitle.ZIndex = 6; dtitle.Parent = drawer
	local dsub = text(self, "", 12, "sub"); dsub.Position = UDim2.fromOffset(20, 38); dsub.Size = UDim2.new(1, -70, 0, 16); dsub.TextWrapped = false; dsub.ZIndex = 6; dsub.Parent = drawer
	local dclose = new("TextButton", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 14), Size = UDim2.fromOffset(30, 30), BorderSizePixel = 0, AutoButtonColor = false, Text = "", ZIndex = 6, Parent = drawer }, { corner(15) })
	bind(self, dclose, "BackgroundColor3", "elem")
	local dcx = text(self, "×", 18, "sub", T.bold, Enum.TextXAlignment.Center); dcx.Size = UDim2.fromScale(1, 1); dcx.TextWrapped = false; dcx.ZIndex = 7; dcx.Parent = dclose
	dclose.MouseButton1Click:Connect(function() Sfx.Play("click"); self:ClosePanel() end)
	local dline = new("Frame", { Position = UDim2.fromOffset(0, 62), Size = UDim2.new(1, 0, 0, 1), BorderSizePixel = 0, ZIndex = 6, Parent = drawer })
	bind(self, dline, "BackgroundColor3", "stroke")
	local dbody = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 64), Size = UDim2.new(1, 0, 1, -64), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(), ZIndex = 6, Parent = drawer,
	})
	bind(self, dbody, "ScrollBarImageColor3", "off")
	pad(12, 14, 10, 14).Parent = dbody
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), Parent = dbody })
	self.panel = { frame = drawer, title = dtitle, sub = dsub, body = dbody, mod = nil, w = DRAWER_W }

	-- toasts
	self.toasts = new("Frame", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -18, 1, -18), Size = UDim2.fromOffset(330, 460), BackgroundTransparency = 1, Parent = gui })
	new("UIListLayout", { Padding = UDim.new(0, 8), VerticalAlignment = Enum.VerticalAlignment.Bottom, HorizontalAlignment = Enum.HorizontalAlignment.Right, Parent = self.toasts })

	tween(self.scale, .35, { Scale = self.baseScale }, Enum.EasingStyle.Quint)
	Sfx.Preload()
	task.delay(.1, function() Sfx.Play("open") end)
	if self.blur and self.blurSize > 0 then tween(self.blur, .4, { Size = self.blurSize }) end
	return self
end

-- TABS ----------------------------------------------------------------------------------------------------------------------
-- opts: { Icon = n, Section = "Combat" }. Tabs with the same Section sit together under one small heading.
function UI:Tab(name, opts)
	opts = opts or {}
	local idx = #self.tabs + 1
	self.navOrder = self.navOrder + 1
	if opts.Section and opts.Section ~= self.lastNavSection then
		self.lastNavSection = opts.Section
		local h = text(self, opts.Section, 11, "sub", T.bold)
		h.Size = UDim2.new(1, 0, 0, 26); h.LayoutOrder = self.navOrder; h.TextWrapped = false; h.TextYAlignment = Enum.TextYAlignment.Bottom
		h.Parent = self.nav
		pad(10, 0, 0, 6).Parent = h
		self.navOrder = self.navOrder + 1
	end
	local btn = new("TextButton", { Size = UDim2.new(1, 0, 0, 33), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", LayoutOrder = self.navOrder, BorderSizePixel = 0, Parent = self.nav }, { corner(10) })
	bind(self, btn, "BackgroundColor3", "accentDim")
	local ico = opts.Icon and Icons.Make(btn, opts.Icon, 17, UDim2.new(0, 12, .5, -8.5))
	if ico then bind(self, ico, "ImageColor3", "sub") end
	local baseX = ico and 38 or 14
	local txt = text(self, name, 13, "sub", T.semi); txt.Position = UDim2.fromOffset(baseX, 0); txt.Size = UDim2.new(1, -baseX - 6, 1, 0); txt.TextWrapped = false; txt.Parent = btn

	local page = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = idx, Visible = false, Parent = self.content })
	new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = page })
	local header = text(self, name, 12, "sub", T.bold)
	header.Size = UDim2.new(1, 0, 0, 18); header.LayoutOrder = -1; header.Visible = false; header.TextWrapped = false; header.Parent = page

	local tab = { name = name, btn = btn, txt = txt, ico = ico, page = page, header = header, win = self, index = idx, iconIdx = opts.Icon, modCount = 0 }
	setmetatable(tab, { __index = UI.TabMethods })
	table.insert(self.tabs, tab)

	btn.MouseEnter:Connect(function()
		if self.active ~= tab then tween(btn, .12, { BackgroundTransparency = .5, BackgroundColor3 = T.elem }); tween(txt, .12, { TextColor3 = T.text }) end
	end)
	btn.MouseLeave:Connect(function()
		if self.active ~= tab then tween(btn, .12, { BackgroundTransparency = 1 }); tween(txt, .12, { TextColor3 = T.sub }) end
	end)
	btn.MouseButton1Click:Connect(function()
		if self.searchBox.Text ~= "" then self.searchBox.Text = "" end
		if self.active ~= tab then Sfx.Play("tab") end
		self:Select(tab)
	end)
	if not self.active then self:Select(tab) end
	return tab
end

function UI:Select(tab)
	self.active = tab
	self:ClosePanel(true)
	for _, t in ipairs(self.tabs) do
		local on = t == tab
		tween(t.btn, .15, { BackgroundTransparency = on and 0 or 1, BackgroundColor3 = T.accentDim })
		tween(t.txt, .15, { TextColor3 = on and T.text or T.sub })
		if t.ico then tween(t.ico, .15, { ImageColor3 = on and T.text or T.sub }) end
		if not on then t.page.Visible = false end
	end
	self.pageTitle.Text = tab.name
	self.pageSub.Text = tab.modCount > 0 and (tab.modCount .. (tab.modCount == 1 and " module" or " modules")) or ""
	tab.page.Visible = true
	self.content.CanvasPosition = Vector2.zero
end

-- DRAWER ----------------------------------------------------------------------------------------------------------------------
function UI:OpenPanel(mod)
	local P = self.panel
	if P.mod and P.mod ~= mod then P.mod.sf.Visible = false; if P.mod.card then P.mod.card.setActive(false) end end
	P.mod = mod
	P.title.Text = mod.name
	local n = mod.count()
	P.sub.Text = (mod.tab and (mod.tab.name .. "  -  ") or "") .. n .. (n == 1 and " setting" or " settings")
	mod.sf.Visible = true
	if mod.card then mod.card.setActive(true) end
	P.body.CanvasPosition = Vector2.zero
	P.frame.Visible = true
	tween(P.frame, .28, { Position = UDim2.new(1, -10, 0, 10) }, Enum.EasingStyle.Quint)
	tween(self.content, .28, { Size = UDim2.new(1, -(SIDE_W + 1 + P.w + 20), 1, -TOP_H) }, Enum.EasingStyle.Quint)
end

function UI:ClosePanel(instant)
	local P = self.panel
	if not P or not P.mod then return end
	local mod = P.mod
	P.mod = nil
	if mod.card then mod.card.setActive(false) end
	local d = instant and .01 or .22
	tween(self.content, d, { Size = UDim2.new(1, -(SIDE_W + 1), 1, -TOP_H) }, Enum.EasingStyle.Quint)
	tween(P.frame, d, { Position = UDim2.new(1, P.w + 30, 0, 10) }, Enum.EasingStyle.Quint)
	task.delay(instant and .02 or .25, function()
		if P.mod == nil then P.frame.Visible = false end
		if P.mod ~= mod then mod.sf.Visible = false end
	end)
end

-- SEARCH ----------------------------------------------------------------------------------------------------------------------
function UI:_search(q)
	q = q:lower():gsub("^%s+", ""):gsub("%s+$", "")
	if q == "" then
		for _, t in ipairs(self.tabs) do t.header.Visible = false; t.page.Visible = t == self.active end
		for _, r in ipairs(self.rows) do r.frame.Visible = true end
		for _, sec in ipairs(self.sections) do
			if sec.collapsed then for _, fr in ipairs(sec.rows) do fr.Visible = false end end
		end
		return
	end
	self:ClosePanel(true)
	local hits = {}
	for _, r in ipairs(self.rows) do
		local m = r.name:find(q, 1, true) ~= nil or r.tab.name:lower():find(q, 1, true) ~= nil
		r.frame.Visible = m
		if m then hits[r.tab] = true end
	end
	for _, t in ipairs(self.tabs) do
		local has = hits[t] == true
		t.header.Visible = has
		t.page.Visible = has
	end
	self.content.CanvasPosition = Vector2.zero
end

-- TOASTS ----------------------------------------------------------------------------------------------------------------------
local KINDS = {
	info = { color = Color3.fromRGB(150, 160, 255), sound = "notify" },
	success = { color = Color3.fromRGB(70, 200, 120), sound = "success" },
	warn = { color = Color3.fromRGB(240, 90, 80), sound = "warn" },
}
local function guessKind(textv)
	local l = textv:lower()
	if l:find("not found", 1, true) or l:find("failed", 1, true) or l:find("error", 1, true) or l:find("nothing", 1, true) or l:find("no pickup", 1, true)
		or l:find("changed its", 1, true) or l:find("missing", 1, true) or l:find("can't", 1, true) or l:find("cannot", 1, true) or l:find("no item", 1, true) then return "warn" end
	if l:find("learned", 1, true) or l:find("picked up", 1, true) or l:find("loaded", 1, true) or l:find("restored", 1, true) or l:find("applied", 1, true)
		or l:find("saved", 1, true) or l:find(" on", 1, true) or l:find("normal", 1, true) then return "success" end
	return "info"
end

function UI:Notify(str, seconds, kind)
	str = tostring(str)
	kind = KINDS[kind or ""] and kind or guessKind(str)
	local K = KINDS[kind]
	seconds = seconds or 3
	Sfx.Play(K.sound, .7)
	local slot = new("Frame", { Size = UDim2.fromOffset(320, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = self.toasts })
	local card = new("Frame", { Position = UDim2.fromOffset(350, 0), Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BorderSizePixel = 0, ClipsDescendants = true, Parent = slot }, { corner(12) })
	bind(self, card, "BackgroundColor3", "panel")
	mkStroke(self, "stroke", 0).Parent = card
	local body = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = card }, { pad(16, 14, 13, 15) })
	new("Frame", { AnchorPoint = Vector2.new(0, .5), Position = UDim2.new(0, 0, .5, -1), Size = UDim2.fromOffset(8, 8), BackgroundColor3 = K.color, BorderSizePixel = 0, Parent = body }, { corner(4) })
	local l = text(self, str, 13, "text"); l.Position = UDim2.fromOffset(18, 0); l.Size = UDim2.new(1, -18, 0, 0); l.AutomaticSize = Enum.AutomaticSize.Y; l.TextYAlignment = Enum.TextYAlignment.Center
	l.Parent = body
	new("UISizeConstraint", { MinSize = Vector2.new(0, 18), Parent = l })
	local track = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(1, 0, 0, 2), BackgroundColor3 = K.color, BackgroundTransparency = 0.85, BorderSizePixel = 0, Parent = card })
	local bar = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = K.color, BorderSizePixel = 0, Parent = track })
	tween(card, .35, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
	tween(bar, seconds, { Size = UDim2.fromScale(0, 1) }, Enum.EasingStyle.Linear)
	task.delay(seconds, function()
		if not slot.Parent then return end
		tween(card, .28, { Position = UDim2.fromOffset(350, 0) }, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
		task.wait(.3)
		pcall(function() slot:Destroy() end)
	end)
end

-- WINDOW STATE -----------------------------------------------------------------------------------------------------------------
function UI:SetVisible(v)
	self.visible = v
	if not v and self.openPicker then pcall(function() self.openPicker:Close() end) end
	if v then
		self.root.Visible = true
		Sfx.Play("open")
		if self.blur and self.blurSize > 0 then tween(self.blur, .3, { Size = self.blurSize }) end
		tween(self.scale, .28, { Scale = self.baseScale }, Enum.EasingStyle.Quint)
	else
		pcall(function() self.searchBox:ReleaseFocus() end)
		Sfx.Play("close")
		if self.blur then tween(self.blur, .2, { Size = 0 }) end
		tween(self.scale, .16, { Scale = self.baseScale * .96 })
		task.delay(.18, function() if not self.visible then self.root.Visible = false end end)
	end
end
function UI:Toggle() self:SetVisible(not self.visible) end

function UI:SetScale(s)
	self.baseScale = (self.autoScale or 1) * s
	tween(self.scale, .2, { Scale = self.baseScale })
end

function UI:SetBlur(size)
	self.blurSize = size
	if self.blur and self.visible then tween(self.blur, .3, { Size = size }) end
end

function UI:Destroy()
	pcall(function() if self.blur then self.blur:Destroy() end end)
	for _, c in ipairs(self.conns) do pcall(function() c:Disconnect() end) end
	self.gui:Destroy()
end

-- COMPONENTS ------------------------------------------------------------------------------------------------------------------
local M = {}
UI.TabMethods = M

-- settings registry: every Toggle / Slider / Keybind is remembered under "Tab/Module/Name" so a whole config can be saved and applied
local function register(self, o, kind, obj)
	if o.NoSave then return end
	local win = self.win
	local id = (self.realTab or self).name .. "/" .. (self.modName and (self.modName .. "/") or "") .. o.Name
	if win.flags[id] then
		local n = 2
		while win.flags[id .. "#" .. n] do n = n + 1 end
		id = id .. "#" .. n
	end
	win.flags[id] = { kind = kind, obj = obj }
end

local function colorHex(c) return string.format("#%02X%02X%02X", math.floor(c.R * 255 + .5), math.floor(c.G * 255 + .5), math.floor(c.B * 255 + .5)) end
local function hexColor(t)
	t = tostring(t or ""):gsub("[#%s]", "")
	if #t ~= 6 or not t:match("^%x+$") then return nil end
	return Color3.fromRGB(tonumber(t:sub(1, 2), 16), tonumber(t:sub(3, 4), 16), tonumber(t:sub(5, 6), 16))
end

-- every saved setting: toggles, sliders, keybinds, colours, text boxes and choices (the "cycle" buttons)
function UI:GetConfig()
	local out = {}
	for id, f in pairs(self.flags) do
		local ok, v = pcall(function() return f.obj:Get() end)
		if ok and v ~= nil then
			if f.kind == "key" then v = v and v.Name or ""
			elseif f.kind == "color" then v = colorHex(v) end
			out[id] = v
		end
	end
	return out
end

-- sliders and keybinds first, toggles last: a module reads its sliders when it turns on
function UI:ApplyConfig(cfg)
	for pass = 1, 2 do
		for id, f in pairs(self.flags) do
			local v = cfg[id]
			if v ~= nil and ((f.kind == "toggle") == (pass == 2)) then
				pcall(function()
					if f.kind == "key" then
						f.obj:Set(v ~= "" and Enum.KeyCode[v] or nil)
					elseif f.kind == "color" then
						local c = hexColor(v)
						if c and colorHex(f.obj:Get()) ~= colorHex(c) then f.obj:Set(c) end
					elseif f.obj:Get() ~= v then
						f.obj:Set(v)
					end
				end)
			end
		end
	end
end

-- a settings row: a quiet rounded card that grows with its label (long names wrap instead of being cut off)
local function row(tab, name, minH, fixed)
	tab.grid = nil
	local win = tab.win
	local f = new("Frame", { Size = UDim2.new(1, 0, 0, minH or 46), AutomaticSize = fixed and Enum.AutomaticSize.None or Enum.AutomaticSize.Y, BorderSizePixel = 0, Parent = tab.page }, { corner(12) })
	bind(win, f, "BackgroundColor3", "panel")
	local st = mkStroke(win, "stroke", 0); st.Parent = f
	f.MouseEnter:Connect(function() tween(f, .12, { BackgroundColor3 = T.elem }) end)
	f.MouseLeave:Connect(function() tween(f, .15, { BackgroundColor3 = T.panel }) end)
	table.insert(win.rows, { frame = f, name = name:lower(), tab = tab.realTab or tab })
	local cs = tab.curSection
	if cs then
		table.insert(cs.rows, f)
		if cs.collapsed then f.Visible = false end
		if cs.count then cs.count() end
	end
	return f, st
end

local function rowLabel(win, f, str, rightRoom, y)
	local l = text(win, str, 13, "text")
	l.Position = UDim2.fromOffset(16, y or 13); l.Size = UDim2.new(1, -(rightRoom + 30), 0, 0); l.AutomaticSize = Enum.AutomaticSize.Y; l.Parent = f
	new("UISizeConstraint", { MinSize = Vector2.new(0, 20), Parent = l })
	return l
end

function M:Section(o)
	local name = type(o) == "table" and o.Name or tostring(o)
	local win = self.win
	local f = new("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Parent = self.page })
	self.grid = nil
	local l = text(win, name, 12, "sub", T.bold); l.Position = UDim2.fromOffset(4, 6); l.Size = UDim2.new(1, -70, 1, -6); l.TextWrapped = false; l.TextYAlignment = Enum.TextYAlignment.Bottom; l.Parent = f
	local chev = text(win, "v", 12, "sub", T.bold, Enum.TextXAlignment.Right); chev.AnchorPoint = Vector2.new(1, 1); chev.Position = UDim2.new(1, -4, 1, 0); chev.Size = UDim2.fromOffset(50, 16); chev.TextWrapped = false; chev.Parent = f
	local sec = { rows = {}, collapsed = type(o) == "table" and o.Collapsed == true }
	local function refreshHead() chev.Text = sec.collapsed and (#sec.rows .. "  >") or "v" end
	sec.count = refreshHead
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = f })
	hit.MouseEnter:Connect(function() tween(l, .12, { TextColor3 = T.text }) end)
	hit.MouseLeave:Connect(function() tween(l, .12, { TextColor3 = T.sub }) end)
	hit.MouseButton1Click:Connect(function()
		sec.collapsed = not sec.collapsed
		for _, r in ipairs(sec.rows) do r.Visible = not sec.collapsed end
		refreshHead()
	end)
	self.curSection = sec
	table.insert(win.sections, sec)
	table.insert(win.rows, { frame = f, name = "\0", tab = self.realTab or self })
	return { frame = f, Section = sec }
end

function M:Label(o)
	local win = self.win
	local f = row(self, o.Name, 42)
	local n = text(win, o.Name, 13, "sub"); n.Position = UDim2.fromOffset(16, 12); n.Size = UDim2.new(.5, -16, 0, 0); n.AutomaticSize = Enum.AutomaticSize.Y; n.Parent = f
	local v = text(win, tostring(o.Value or "-"), 13, "text", T.semi, Enum.TextXAlignment.Right)
	v.Position = UDim2.new(.5, 0, 0, 12); v.Size = UDim2.new(.5, -16, 0, 0); v.AutomaticSize = Enum.AutomaticSize.Y; v.Parent = f
	return { Set = function(_, x) v.Text = tostring(x) end, frame = f }
end

-- a small pill button (left aligned), like the executor's own buttons
function M:Button(o)
	local win = self.win
	self.grid = nil
	local b = new("TextButton", { Size = UDim2.fromOffset(0, 34), AutomaticSize = Enum.AutomaticSize.X, BorderSizePixel = 0, AutoButtonColor = false, Text = "", Parent = self.page }, { corner(17), pad(18, 18, 0, 0) })
	if o.Order then b.LayoutOrder = o.Order end
	bind(win, b, "BackgroundColor3", "elem")
	local t = text(win, o.Name, 13, "text", T.semi, Enum.TextXAlignment.Center); t.Size = UDim2.fromOffset(0, 34); t.AutomaticSize = Enum.AutomaticSize.X; t.TextWrapped = false; t.Parent = b
	b.MouseEnter:Connect(function() tween(b, .12, { BackgroundColor3 = T.hover }) end)
	b.MouseLeave:Connect(function() tween(b, .15, { BackgroundColor3 = T.elem }) end)
	b.MouseButton1Click:Connect(function()
		Sfx.Play("click")
		b.BackgroundColor3 = T.strokeOn; tween(b, .3, { BackgroundColor3 = T.hover })
		if o.Callback then task.spawn(o.Callback) end
	end)
	table.insert(win.rows, { frame = b, name = o.Name:lower(), tab = self.realTab or self })
	local cs = self.curSection
	if cs then
		table.insert(cs.rows, b)
		if cs.collapsed then b.Visible = false end
		if cs.count then cs.count() end
	end
	return {
		frame = b,
		SetText = function(_, s) t.Text = s end,
		Destroy = function()
			for i, r in ipairs(win.rows) do if r.frame == b then table.remove(win.rows, i); break end end
			b:Destroy()
		end,
	}
end

function M:TextBox(o)
	local win = self.win
	local f = row(self, o.Name, 48)
	rowLabel(win, f, o.Name, 160)
	local bg = new("Frame", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -12, .5, 0), Size = UDim2.fromOffset(150, 30), BorderSizePixel = 0, Parent = f }, { corner(15) })
	bind(win, bg, "BackgroundColor3", "elem")
	local box = new("TextBox", { BackgroundTransparency = 1, Size = UDim2.new(1, -24, 1, 0), Position = UDim2.fromOffset(12, 0), Text = o.Default or "", PlaceholderText = o.Placeholder or "",
		Font = T.font, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, Parent = bg })
	bind(win, box, "TextColor3", "text"); bind(win, box, "PlaceholderColor3", "sub")
	box.FocusLost:Connect(function() if o.Callback then task.spawn(o.Callback, box.Text) end end)
	local obj = { frame = f }
	function obj:Get() return box.Text end
	function obj:Set(t, silent) box.Text = tostring(t); if not silent and o.Callback then task.spawn(o.Callback, box.Text) end end
	register(self, o, "text", obj)
	return obj
end

-- Choice: a row with a pill that cycles through the options (click = next, right-click = previous). Saved with the config.
function M:Choice(o)
	local win = self.win
	local f = row(self, o.Name, 48)
	rowLabel(win, f, o.Name, 170)
	local opts_ = o.Options
	local idx = 1
	for i, v in ipairs(opts_) do if v == o.Default then idx = i end end
	local btn = new("TextButton", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -12, .5, 0), Size = UDim2.fromOffset(150, 30), BorderSizePixel = 0, AutoButtonColor = false, Text = "", Parent = f }, { corner(15) })
	bind(win, btn, "BackgroundColor3", "elem")
	local txt = text(win, "", 12, "text", T.semi, Enum.TextXAlignment.Center); txt.Size = UDim2.new(1, -16, 1, 0); txt.Position = UDim2.fromOffset(8, 0); txt.TextWrapped = false; txt.TextTruncate = Enum.TextTruncate.AtEnd; txt.Parent = btn
	local obj = { frame = f }
	local function show() txt.Text = tostring(opts_[idx]) end
	local function pickIdx(i, silent)
		idx = i
		show()
		if not silent then
			Sfx.Play("click", .5)
			if o.Callback then task.spawn(o.Callback, opts_[idx]) end
		end
	end
	function obj:Get() return opts_[idx] end
	function obj:Set(v, silent) for i, x in ipairs(opts_) do if x == v then pickIdx(i, silent); return end end end
	btn.MouseButton1Click:Connect(function() pickIdx(idx % #opts_ + 1) end)
	btn.MouseButton2Click:Connect(function() pickIdx((idx - 2) % #opts_ + 1) end)
	btn.MouseEnter:Connect(function() tween(btn, .12, { BackgroundColor3 = T.hover }) end)
	btn.MouseLeave:Connect(function() tween(btn, .15, { BackgroundColor3 = T.elem }) end)
	show()
	register(self, o, "choice", obj)
	return obj
end

-- switch: off = grey track + grey knob, on = bright track + dark knob (like the executor's own toggles)
local function makeSwitch(win, parent, anchor, pos, getState)
	local sw = new("Frame", { AnchorPoint = anchor, Position = pos, Size = UDim2.fromOffset(40, 22), BorderSizePixel = 0, Parent = parent }, { corner(11) })
	local knob = new("Frame", { AnchorPoint = Vector2.new(0, .5), Position = UDim2.new(0, 3, .5, 0), Size = UDim2.fromOffset(16, 16), BorderSizePixel = 0, Parent = sw }, { corner(8) })
	local function trackColor() return getState() and T.accent or T.off end
	local function knobColor() return getState() and T.bg or Color3.fromRGB(176, 176, 184) end
	bind(win, sw, "BackgroundColor3", trackColor)
	bind(win, knob, "BackgroundColor3", knobColor)
	local function set(v, animate)
		local pos_ = UDim2.new(0, v and 21 or 3, .5, 0)
		if animate then
			tween(sw, .16, { BackgroundColor3 = trackColor() }); tween(knob, .16, { BackgroundColor3 = knobColor(), Position = pos_ })
		else
			sw.BackgroundColor3 = trackColor(); knob.BackgroundColor3 = knobColor(); knob.Position = pos_
		end
	end
	return sw, set
end

function M:Toggle(o)
	local win = self.win
	local f, rowStroke = row(self, o.Name, 48)
	rowLabel(win, f, o.Name, 56)
	local state = false
	local sw, setSwitch = makeSwitch(win, f, Vector2.new(1, .5), UDim2.new(1, -14, .5, 0), function() return state end)
	local obj = {}
	local function apply(v, silent)
		state = v
		setSwitch(v, not silent)
		if not silent then
			Sfx.Play(v and "on" or "off")
			if o.Callback then task.spawn(o.Callback, v) end
		end
	end
	function obj:Set(v, silent) apply(v, silent) end
	function obj:Get() return state end
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = f })
	hit.MouseButton1Click:Connect(function() apply(not state) end)
	apply(o.Default == true, true)
	obj.frame, obj.hit = f, hit
	register(self, o, "toggle", obj)
	return obj
end

-- MODULE ROW ------------------------------------------------------------------------------------------------------------------
-- A module is a slim row: name, how many settings, gear (opens the drawer), switch. Click the row to switch it on / off.
-- local m = tab:Module({ Name = "Suspension", Default = false, Callback = function(on) end })
-- m:Slider({...}) / m:Toggle({...}) / m:Keybind({...}) / m:Button({...}) / m:Label({...}) add rows to its drawer.
function M:Module(o)
	local win = self.win
	local realTab = self.realTab or self
	realTab.modCount = realTab.modCount + 1
	self.grid = nil
	local card = new("Frame", { Size = UDim2.new(1, 0, 0, 56), BorderSizePixel = 0, Parent = self.page }, { corner(12) })
	local cstroke = new("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = card })

	local state, count, active = false, 0, false
	local obj = {}
	bind(win, card, "BackgroundColor3", "panel")
	bind(win, cstroke, "Color", function() return (state or active) and T.strokeOn or T.stroke end)

	local nameL = text(win, o.Name, 13.5, "text", T.semi); nameL.Position = UDim2.fromOffset(16, 10); nameL.Size = UDim2.new(1, -150, 0, 18); nameL.TextWrapped = false; nameL.TextTruncate = Enum.TextTruncate.AtEnd; nameL.Parent = card
	local statL = text(win, "", 12, "sub"); statL.Position = UDim2.fromOffset(16, 29); statL.Size = UDim2.new(1, -150, 0, 16); statL.TextWrapped = false; statL.Parent = card
	local sw, setSwitch = makeSwitch(win, card, Vector2.new(1, .5), UDim2.new(1, -16, .5, 0), function() return state end)

	local function status()
		statL.Text = count > 0 and (count .. (count == 1 and " setting" or " settings")) or (state and "On" or "Off")
	end
	local function paint(animate)
		local c = (state or active) and T.strokeOn or T.stroke
		if animate then tween(cstroke, .15, { Color = c }) else cstroke.Color = c end
	end
	local function apply(v, silent)
		state = v
		setSwitch(v, not silent); paint(not silent); status()
		if not silent then
			Sfx.Play(v and "on" or "off")
			if o.Callback then task.spawn(o.Callback, v) end
		end
	end
	function obj:Set(v, silent) apply(v, silent) end
	function obj:Get() return state end
	obj.frame = card

	local sf = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false, Parent = win.panel.body })
	new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = sf })
	local sub = { page = sf, win = win, realTab = realTab, modName = o.Name }
	setmetatable(sub, { __index = M })
	local mod = { name = o.Name, sf = sf, tab = realTab, count = function() return count end, card = { setActive = function(v) active = v; paint(true) end } }
	local function togglePanel()
		if count == 0 then return end
		if win.panel.mod == mod then win:ClosePanel() else win:OpenPanel(mod) end
	end
	function obj:SetOpen(v) if v then win:OpenPanel(mod) elseif win.panel.mod == mod then win:ClosePanel() end end

	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = card })
	hit.MouseButton1Click:Connect(function() apply(not state) end)
	hit.MouseButton2Click:Connect(togglePanel)
	hit.MouseEnter:Connect(function() tween(card, .12, { BackgroundColor3 = T.elem }) end)
	hit.MouseLeave:Connect(function() tween(card, .15, { BackgroundColor3 = T.panel }) end)
	-- gear, left of the switch
	local gear = new("TextButton", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -66, .5, 0), Size = UDim2.fromOffset(32, 32), BorderSizePixel = 0, AutoButtonColor = false, Text = "", Visible = false, ZIndex = 3, Parent = card }, { corner(16) })
	gear.BackgroundTransparency = 1
	bind(win, gear, "BackgroundColor3", "hover")
	local gi = Icons.Make(gear, 9, 17, UDim2.new(.5, -8.5, .5, -8.5))
	if gi then bind(win, gi, "ImageColor3", "sub"); gi.ZIndex = 4
	else
		local gt = text(win, "...", 16, "sub", T.bold, Enum.TextXAlignment.Center); gt.Size = UDim2.fromScale(1, 1); gt.TextWrapped = false; gt.ZIndex = 4; gt.Parent = gear
	end
	gear.MouseButton1Click:Connect(function() Sfx.Play("click"); togglePanel() end)
	gear.MouseEnter:Connect(function() tween(gear, .12, { BackgroundTransparency = 0 }); if gi then tween(gi, .12, { ImageColor3 = T.text }) end end)
	gear.MouseLeave:Connect(function() tween(gear, .15, { BackgroundTransparency = 1 }); if gi then tween(gi, .15, { ImageColor3 = T.sub }) end end)

	local ent = { frame = card, name = o.Name:lower(), tab = realTab }
	table.insert(win.rows, ent)
	for _, k in ipairs({ "Toggle", "Slider", "Keybind", "Button", "Label", "TextBox", "ColorPicker", "Choice", "Section" }) do
		obj[k] = function(_, opts)
			if k ~= "Section" then
				count = count + 1
				gear.Visible = true; status()
				if opts and opts.Name then ent.name = ent.name .. " " .. tostring(opts.Name):lower() end
			end
			return M[k](sub, opts)
		end
	end
	apply(o.Default == true, true)
	register({ win = win, realTab = realTab }, o, "toggle", obj)
	return obj
end

-- SLIDER ----------------------------------------------------------------------------------------------------------------------
function M:Slider(o)
	local win = self.win
	local f = row(self, o.Name, 60)
	new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = f })
	pad(16, 16, 12, 14).Parent = f
	local head = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 1, Parent = f })
	local n = text(win, o.Name, 13, "text"); n.Size = UDim2.new(1, -74, 0, 0); n.AutomaticSize = Enum.AutomaticSize.Y; n.Parent = head
	new("UISizeConstraint", { MinSize = Vector2.new(0, 18), Parent = n })
	local val = text(win, "", 13, "sub", T.semi, Enum.TextXAlignment.Right); val.AnchorPoint = Vector2.new(1, 0); val.Position = UDim2.fromScale(1, 0); val.Size = UDim2.fromOffset(70, 18); val.TextWrapped = false; val.Parent = head
	local zone = new("Frame", { Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2, Parent = f })
	local track = new("Frame", { AnchorPoint = Vector2.new(0, .5), Position = UDim2.fromScale(0, .5), Size = UDim2.new(1, 0, 0, 4), BorderSizePixel = 0, Parent = zone }, { corner(2) })
	bind(win, track, "BackgroundColor3", "off")
	local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0, Parent = track }, { corner(2) })
	bind(win, fill, "BackgroundColor3", "accent")
	local knob = new("Frame", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(0, .5), Size = UDim2.fromOffset(14, 14), BorderSizePixel = 0, ZIndex = 2, Parent = track }, { corner(7) })
	bind(win, knob, "BackgroundColor3", "accent")
	local min, max, step = o.Min, o.Max, o.Step or 1
	local value
	local obj = {}
	local function set(v, silent)
		v = math.clamp(math.floor((v - min) / step + .5) * step + min, min, max)
		value = v
		local p = (v - min) / (max - min)
		fill.Size = UDim2.fromScale(p, 1); knob.Position = UDim2.fromScale(p, .5)
		val.Text = (step < 1 and string.format("%.2f", v) or tostring(v)) .. (o.Suffix or "")
		if not silent and o.Callback then task.spawn(o.Callback, v) end
	end
	function obj:Set(v, silent) set(v, silent) end
	function obj:Get() return value end
	local dragging = false
	local function fromInput(i) set(min + math.clamp((i.Position.X - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1) * (max - min)) end
	local hit = new("TextButton", { Size = UDim2.new(1, 0, 1, 10), Position = UDim2.fromOffset(0, -5), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = zone })
	hit.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging = true; tween(knob, .1, { Size = UDim2.fromOffset(18, 18) }); fromInput(i)
		end
	end)
	table.insert(win.conns, UIS.InputChanged:Connect(function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then fromInput(i) end
	end))
	table.insert(win.conns, UIS.InputEnded:Connect(function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
			dragging = false; tween(knob, .1, { Size = UDim2.fromOffset(14, 14) }); Sfx.Play("click", .35)
		end
	end))
	set(o.Default or min, true)
	obj.frame = f
	register(self, o, "slider", obj)
	return obj
end

-- KEYBIND ---------------------------------------------------------------------------------------------------------------------
-- click, then press a key to bind it (Escape clears). Callback(key) gets an Enum.KeyCode or nil.
function M:Keybind(o)
	local win = self.win
	local f = row(self, o.Name, 48)
	rowLabel(win, f, o.Name, 120)
	local btn = new("TextButton", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -12, .5, 0), Size = UDim2.fromOffset(104, 30), BorderSizePixel = 0, AutoButtonColor = false, Text = "", Parent = f }, { corner(15) })
	bind(win, btn, "BackgroundColor3", "elem")
	local txt = text(win, "", 12, "text", T.semi, Enum.TextXAlignment.Center); txt.Size = UDim2.fromScale(1, 1); txt.TextWrapped = false; txt.Parent = btn
	local key, listening, conn = o.Default, false, nil
	local obj = {}
	local function show()
		txt.Text = listening and "Press a key" or (key and key.Name or "None")
		tween(txt, .12, { TextColor3 = listening and T.strokeOn or T.text })
		tween(btn, .12, { BackgroundColor3 = listening and T.hover or T.elem })
	end
	function obj:Get() return key end
	-- still "listening" for a moment after a bind, so the key you just chose does not also fire its action
	function obj:IsListening() return listening or os.clock() - (obj.boundAt or 0) < 0.25 end
	function obj:Set(k, silent) key = k; show(); if not silent and o.Callback then task.spawn(o.Callback, key) end end
	btn.MouseButton1Click:Connect(function()
		if listening then return end
		listening = true
		show()
		conn = UIS.InputBegan:Connect(function(i)
			if i.UserInputType ~= Enum.UserInputType.Keyboard then return end
			conn:Disconnect()
			key = (i.KeyCode ~= Enum.KeyCode.Escape) and i.KeyCode or nil
			listening = false
			obj.boundAt = os.clock()
			show()
			if o.Callback then task.spawn(o.Callback, key) end
		end)
		table.insert(win.conns, conn)
	end)
	show()
	obj.frame = f
	register(self, o, "key", obj)
	return obj
end

-- COLOUR PICKER ---------------------------------------------------------------------------------------------------------------
-- A swatch that opens a popup with a saturation/brightness square and a hue bar. Drag to choose; Callback(color, final)
-- runs while dragging (throttled, final=false) and once more on release / close (final=true).
function M:ColorPicker(o)
	local win = self.win
	local f = row(self, o.Name, 48)
	rowLabel(win, f, o.Name, 64)
	local color = o.Default or T.accent
	local h, s, v = color:ToHSV()
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Parent = f })
	local sw = new("Frame", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -14, .5, 0), Size = UDim2.fromOffset(44, 26), BackgroundColor3 = color, BorderSizePixel = 0, Parent = f }, { corner(13) })
	new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 1, Transparency = .8, Parent = sw })

	local obj = {}
	local pop, svBox, svCur, hueCur, hexLbl, prev, hueBar
	local lastFire = 0
	local function hex() return string.format("#%02X%02X%02X", math.floor(color.R * 255 + .5), math.floor(color.G * 255 + .5), math.floor(color.B * 255 + .5)) end
	local function fire(final)
		if not o.Callback then return end
		if final or os.clock() - lastFire > 0.08 then
			lastFire = os.clock()
			task.spawn(o.Callback, color, final == true)
		end
	end
	local function refresh()
		color = Color3.fromHSV(h, s, v)
		sw.BackgroundColor3 = color
		if pop then
			svBox.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
			svCur.Position = UDim2.fromScale(s, 1 - v)
			hueCur.Position = UDim2.fromScale(h, .5)
			hexLbl.Text = hex()
			prev.BackgroundColor3 = color
		end
	end
	function obj:Get() return color end
	function obj:Set(c, silent) h, s, v = c:ToHSV(); refresh(); if not silent then fire(true) end end

	local function build()
		pop = new("Frame", { Size = UDim2.fromOffset(240, 270), BackgroundColor3 = T.panel, BorderSizePixel = 0, ZIndex = 30, Visible = false, Parent = win.gui }, { corner(12) })
		new("UIStroke", { Color = T.stroke, Thickness = 1, Parent = pop })
		new("TextLabel", { BackgroundTransparency = 1, Text = o.Name, TextSize = 13, Font = T.bold, TextColor3 = T.text, TextXAlignment = Enum.TextXAlignment.Left, Position = UDim2.fromOffset(14, 10), Size = UDim2.new(1, -50, 0, 18), Parent = pop })
		local x = new("TextButton", { Position = UDim2.new(1, -32, 0, 6), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = T.elem, BorderSizePixel = 0, AutoButtonColor = false, Text = "×", TextSize = 18, Font = T.bold, TextColor3 = T.sub, Parent = pop }, { corner(13) })
		x.MouseButton1Click:Connect(function() obj:Close() end)

		svBox = new("Frame", { Position = UDim2.fromOffset(12, 38), Size = UDim2.fromOffset(216, 142), BackgroundColor3 = Color3.fromHSV(h, 1, 1), BorderSizePixel = 0, ClipsDescendants = true, Parent = pop }, { corner(8) })
		local white = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = svBox })
		new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }), Parent = white })
		local black = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, Parent = svBox })
		new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }), Parent = black })
		svCur = new("Frame", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(14, 14), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 2, Parent = svBox }, { corner(7) })
		new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 2, Parent = svCur })

		hueBar = new("Frame", { Position = UDim2.fromOffset(12, 192), Size = UDim2.fromOffset(216, 14), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = pop }, { corner(7) })
		new("UIGradient", { Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)), ColorSequenceKeypoint.new(1 / 6, Color3.fromRGB(255, 255, 0)),
			ColorSequenceKeypoint.new(2 / 6, Color3.fromRGB(0, 255, 0)), ColorSequenceKeypoint.new(3 / 6, Color3.fromRGB(0, 255, 255)),
			ColorSequenceKeypoint.new(4 / 6, Color3.fromRGB(0, 0, 255)), ColorSequenceKeypoint.new(5 / 6, Color3.fromRGB(255, 0, 255)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0)) }), Parent = hueBar })
		hueCur = new("Frame", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(8, 22), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 2, Parent = hueBar }, { corner(4) })
		new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 1, Parent = hueCur })

		prev = new("Frame", { Position = UDim2.fromOffset(12, 222), Size = UDim2.fromOffset(36, 32), BackgroundColor3 = color, BorderSizePixel = 0, Parent = pop }, { corner(8) })
		hexLbl = new("TextLabel", { BackgroundTransparency = 1, Text = hex(), TextSize = 13, Font = T.bold, TextColor3 = T.text, TextXAlignment = Enum.TextXAlignment.Left, Position = UDim2.fromOffset(58, 222), Size = UDim2.fromOffset(90, 32), Parent = pop })
		local rs = new("TextButton", { Position = UDim2.fromOffset(154, 222), Size = UDim2.fromOffset(74, 32), BackgroundColor3 = T.elem, BorderSizePixel = 0, AutoButtonColor = false, Text = "Reset", TextColor3 = T.text, Font = T.font, TextSize = 12, Parent = pop }, { corner(16) })
		rs.MouseButton1Click:Connect(function()
			if o.Default then h, s, v = o.Default:ToHSV(); refresh(); fire(true) end
		end)

		-- dragging (GetMouseLocation matches the ScreenGui's coordinates, which ignore the top bar inset)
		local mode
		local function mousePos(i)
			if i.UserInputType == Enum.UserInputType.Touch then return Vector2.new(i.Position.X, i.Position.Y + GuiService:GetGuiInset().Y) end
			return UIS:GetMouseLocation()
		end
		local function pick(i)
			local m = mousePos(i)
			if mode == "sv" then
				s = math.clamp((m.X - svBox.AbsolutePosition.X) / math.max(svBox.AbsoluteSize.X, 1), 0, 1)
				v = 1 - math.clamp((m.Y - svBox.AbsolutePosition.Y) / math.max(svBox.AbsoluteSize.Y, 1), 0, 1)
			elseif mode == "hue" then
				h = math.clamp((m.X - hueBar.AbsolutePosition.X) / math.max(hueBar.AbsoluteSize.X, 1), 0, 0.999)
			end
			refresh(); fire(false)
		end
		local function grab(target, name)
			local b = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 3, Parent = target })
			b.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then mode = name; pick(i) end
			end)
		end
		grab(svBox, "sv"); grab(hueBar, "hue")
		table.insert(win.conns, UIS.InputChanged:Connect(function(i)
			if mode and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then pick(i) end
		end))
		table.insert(win.conns, UIS.InputEnded:Connect(function(i)
			if mode and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then mode = nil; fire(true) end
		end))
		refresh()
	end

	function obj:Close()
		if pop and pop.Visible then
			pop.Visible = false
			fire(true)
		end
		if win.openPicker == obj then win.openPicker = nil end
	end
	local function open()
		if win.openPicker and win.openPicker ~= obj then win.openPicker:Close() end
		if not pop then build() end
		local sp, ss = sw.AbsolutePosition, win.gui.AbsoluteSize
		pop.Position = UDim2.fromOffset(math.clamp(sp.X + sw.AbsoluteSize.X - 240, 8, math.max(ss.X - 248, 8)), math.clamp(sp.Y + sw.AbsoluteSize.Y + 8, 8, math.max(ss.Y - 278, 8)))
		pop.Visible = true
		refresh()
		win.openPicker = obj
	end
	hit.MouseButton1Click:Connect(function() if pop and pop.Visible then obj:Close() else open() end end)
	obj.frame = f
	register(self, o, "color", obj)
	return obj
end

-- THEME -----------------------------------------------------------------------------------------------------------------------
local PALETTE_KEYS = { "accent", "accentDim", "chip", "gradA", "gradB", "strokeOn", "bg", "panel", "elem", "hover", "stroke", "off" }
local function lift(c, d) return Color3.fromRGB(math.clamp(c.R * 255 + d, 0, 255), math.clamp(c.G * 255 + d, 0, 255), math.clamp(c.B * 255 + d, 0, 255)) end
local DEFAULT_P = {}
for _, k in ipairs(PALETTE_KEYS) do DEFAULT_P[k] = T[k] end
local curP = {}
for k, v in pairs(DEFAULT_P) do curP[k] = v end

-- every colour of the theme derived from two picked colours
function UI.Palette(accent, bg)
	if not accent and not bg then return DEFAULT_P end
	accent, bg = accent or DEFAULT_P.accent, bg or DEFAULT_P.bg
	local white, black = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
	return {
		accent = accent, accentDim = bg:Lerp(accent, .16), chip = accent:Lerp(white, .35), gradA = accent:Lerp(black, .2),
		gradB = accent:Lerp(white, .25), strokeOn = bg:Lerp(accent, .42),
		bg = bg, panel = lift(bg, 5), elem = lift(bg, 14), hover = lift(bg, 22), stroke = lift(bg, 24), off = lift(bg, 51),
	}
end

local function ckey(c) return math.floor(c.R * 255 + .5) .. "," .. math.floor(c.G * 255 + .5) .. "," .. math.floor(c.B * 255 + .5) end

-- recolour everything under root whose colour is a key of map (key -> new Color3); used for the HUD pieces outside the window
function UI.Remap(root, map)
	local function fix(c) return map[ckey(c)] end
	local function visit(o)
		pcall(function()
			if o:IsA("GuiObject") then
				local n = fix(o.BackgroundColor3); if n then o.BackgroundColor3 = n end
				if o:IsA("ImageLabel") or o:IsA("ImageButton") then local ic = fix(o.ImageColor3); if ic then o.ImageColor3 = ic end end
				if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then local t = fix(o.TextColor3); if t then o.TextColor3 = t end end
			elseif o:IsA("UIStroke") then
				local n = fix(o.Color); if n then o.Color = n end
			end
		end)
	end
	visit(root)
	for _, o in ipairs(root:GetDescendants()) do visit(o) end
end

function UI.PaletteMap(old, new)
	local map = {}
	for _, k in ipairs(PALETTE_KEYS) do
		if ckey(old[k]) ~= ckey(new[k]) then map[ckey(old[k])] = new[k] end
	end
	return map
end

-- applies a palette: every bound colour is recomputed; returns the colour map so the HUD can follow
function UI:ApplyPalette(P)
	local map = UI.PaletteMap(curP, P)
	for _, k in ipairs(PALETTE_KEYS) do T[k] = P[k]; curP[k] = P[k] end
	for _, b in ipairs(self.binds) do
		pcall(function() b[1][b[2]] = b[3]() end)
	end
	return map
end

UI.Theme = T
return UI

end

__mods["lib/config"] = function()
-- Config files in the executor workspace:  RagdollSoccer/configs/<name>.json   +   RagdollSoccer/autoload.txt (name of the config to load on start)
local HttpService = game:GetService("HttpService")

local Config = {}
local DIR = "RagdollSoccer"
local CFG = DIR .. "/configs"
local AUTO = DIR .. "/autoload.txt"

Config.Available = (writefile and readfile and isfile) ~= nil

local function ensure()
	pcall(function()
		if not makefolder then return end
		if isfolder then
			if not isfolder(DIR) then makefolder(DIR) end
			if not isfolder(CFG) then makefolder(CFG) end
		else
			makefolder(DIR); makefolder(CFG)
		end
	end)
end

function Config.Clean(name)
	name = tostring(name or ""):gsub("[^%w _%-]", "")
	name = name:gsub("^%s+", ""):gsub("%s+$", "")
	return name:sub(1, 32)
end

local function path(name) return CFG .. "/" .. name .. ".json" end

function Config.List()
	local out = {}
	if not listfiles then return out end
	ensure()
	local ok, files = pcall(listfiles, CFG)
	if not ok or type(files) ~= "table" then return out end
	for _, f in ipairs(files) do
		local n = tostring(f):match("([^/\\]+)%.json$")
		if n then out[#out + 1] = n end
	end
	table.sort(out, function(a, b) return a:lower() < b:lower() end)
	return out
end

function Config.Exists(name)
	if not (isfile and name and name ~= "") then return false end
	local ok, r = pcall(isfile, path(name))
	return ok and r == true
end

function Config.Read(name)
	if not Config.Exists(name) then return nil end
	local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path(name))) end)
	if ok and type(data) == "table" then return data end
	return nil
end

function Config.Write(name, tbl)
	if not (Config.Available and name and name ~= "") then return false end
	ensure()
	local ok = pcall(function() writefile(path(name), HttpService:JSONEncode(tbl)) end)
	return ok
end

function Config.Delete(name)
	if not (delfile and Config.Exists(name)) then return false end
	return pcall(delfile, path(name))
end

function Config.GetAutoload()
	if not (isfile and readfile) then return nil end
	local ok, r = pcall(function() if isfile(AUTO) then return readfile(AUTO) end end)
	if ok and type(r) == "string" then
		r = Config.Clean(r)
		if r ~= "" then return r end
	end
	return nil
end

function Config.SetAutoload(name)
	if not Config.Available then return false end
	ensure()
	return pcall(function() writefile(AUTO, name or "") end)
end

return Config

end

__mods["game/log"] = function()
-- Log: small event log written to RagdollSoccer/log.txt (about every 2 s). When something does not work, this file shows what the script saw and did.
local RunService = game:GetService("RunService")

local Log = { lines = {}, dirty = false }
local conn, acc = nil, 0

function Log.add(msg)
	local l = Log.lines
	l[#l + 1] = ("%s  %s"):format(os.date("%H:%M:%S"), tostring(msg))
	if #l > 300 then table.remove(l, 1) end
	Log.dirty = true
end

local function flush()
	if not Log.dirty or type(writefile) ~= "function" then return end
	Log.dirty = false
	pcall(function()
		if makefolder then pcall(makefolder, "RagdollSoccer") end
		writefile("RagdollSoccer/log.txt", table.concat(Log.lines, "\n"))
	end)
end

function Log.Start()
	if conn then return end
	conn = RunService.Heartbeat:Connect(function(dt)
		acc = acc + dt
		if acc >= 2 then acc = 0; flush() end
	end)
end

function Log.Destroy()
	flush()
	if conn then conn:Disconnect(); conn = nil end
end

return Log

end

__mods["game/world"] = function()
-- World: what the other modules need to know about the match (read from the dump of the game):
--   your character is a "Mannequin" model: a part called Root, a ControllerManager that moves it, attributes Team / Role / BodyState / DribbleId.
--   the ball is Workspace.Ball (tag SoccerBall); its attribute Possessor is the DribbleId of whoever has it (0 = nobody).
--   the goals are the two models / parts tagged SoccerGoalFrame; the pitch runs along X, workspace attribute BlueSide says which side Blue defends.
-- Goals and opponents are cached (the bot asks for them every frame).
local Players = game:GetService("Players")
local CS = game:GetService("CollectionService")
local lp = Players.LocalPlayer

local World = {}
local function horiz(v) return Vector3.new(v.X, 0, v.Z) end
World.horiz = horiz

function World.me()
	local ch = lp.Character
	local root = ch and ch:FindFirstChild("Root")
	if not (root and root:IsA("BasePart")) then return nil end
	return {
		char = ch, root = root, cm = ch:FindFirstChildOfClass("ControllerManager"),
		team = ch:GetAttribute("Team"), role = ch:GetAttribute("Role"), state = ch:GetAttribute("BodyState"), id = ch:GetAttribute("DribbleId"),
	}
end

local ballCache
function World.ball()
	if ballCache and ballCache.Parent then return ballCache end
	local b = workspace:FindFirstChild("Ball")
	if not (b and b:IsA("BasePart")) then
		b = nil
		for _, x in ipairs(CS:GetTagged("SoccerBall")) do
			if x:IsA("BasePart") then b = x; break end
		end
	end
	ballCache = b
	return b
end

-- "me", "other" (somebody has it) or "free"
function World.possession(ball, me)
	local p = ball:GetAttribute("Possessor")
	if type(p) ~= "number" or p == 0 then return "free" end
	if me and me.id and p == me.id then return "me" end
	return "other", p
end

-- both goals { pos, size }, cached for 3 s
local goalsAt, goalsList = -99, {}
function World.goals()
	local now = os.clock()
	if now - goalsAt < 3 and #goalsList >= 2 then return goalsList end
	goalsAt = now
	local list = {}
	for _, inst in ipairs(CS:GetTagged("SoccerGoalFrame")) do
		local pos, size
		if inst:IsA("Model") then
			local ok, cf, sz = pcall(function() return inst:GetBoundingBox() end)
			if ok then pos, size = cf.Position, sz end
		elseif inst:IsA("BasePart") then
			pos, size = inst.Position, inst.Size
		end
		if pos then list[#list + 1] = { pos = pos, size = size } end
	end
	goalsList = list
	return list
end

-- the goal this team shoots at
function World.attackGoal(team)
	if team ~= "Blue" and team ~= "Red" then return nil end
	local g = World.goals()
	if #g < 2 then return nil end
	local cx = 0
	for _, x in ipairs(g) do cx = cx + x.pos.X end
	cx = cx / #g
	local side = workspace:GetAttribute("BlueSide") == 1 and 1 or -1
	local own = team == "Blue" and side or -side -- our own goal is on this side (sign of x)
	for _, x in ipairs(g) do
		if (x.pos.X - cx) * own < 0 then return x end
	end
	return nil
end

-- the goal this team defends; .outward = +1 when it sits at the +X end of the pitch, -1 at the -X end
function World.ownGoal(team)
	local attack = World.attackGoal(team)
	if not attack then return nil end
	for _, x in ipairs(World.goals()) do
		if x ~= attack then
			return { pos = x.pos, size = x.size, outward = x.pos.X >= attack.pos.X and 1 or -1 }
		end
	end
	return nil
end

-- opponents (nearest first) and the opposing keeper's position; the player scan is cached for 0.15 s
local oppAt, oppList, oppKeeper, oppTeam = -99, {}, nil, nil
function World.opponents(team, from)
	local now = os.clock()
	if now - oppAt > 0.15 or oppTeam ~= team then
		oppAt, oppTeam = now, team
		local list, keeper = {}, nil
		for _, p in ipairs(Players:GetPlayers()) do
			local c = p.Character
			if c and p ~= lp then
				local t = c:GetAttribute("Team")
				if t ~= nil and t ~= team then
					local r = c:FindFirstChild("Root")
					if r then
						if c:GetAttribute("Role") == "Goalkeeper" then keeper = r.Position end
						list[#list + 1] = { pos = r.Position }
					end
				end
			end
		end
		oppList, oppKeeper = list, keeper
	end
	for _, o in ipairs(oppList) do o.d = (o.pos - from).Magnitude end
	table.sort(oppList, function(a, b) return a.d < b.d end)
	return oppList, oppKeeper
end

-- where to shoot: a point inside the goal mouth, chosen by `mode`. "Far from keeper" aims at the post on the side the keeper is NOT on, close to the post
-- (the keeper's body is on the other side; a keeper standing in the middle gets the post that is farther from his dive).
function World.shotTarget(team, ballPos, mode)
	local attack = World.attackGoal(team)
	if not attack then return nil end
	local half = math.max(attack.size.Z, attack.size.X) / 2
	local gz = attack.pos.Z
	local zs, ratio = 0, 0.7
	if mode == "Left post" then zs = -1
	elseif mode == "Right post" then zs = 1
	elseif mode == "Centre" then zs = 0
	else
		local _, keeper = World.opponents(team, ballPos)
		if keeper then
			local dz = keeper.Z - gz
			zs = dz >= 0 and -1 or 1
			ratio = math.clamp(0.62 + math.abs(dz) / math.max(half, 1) * -0.1 + 0.18, 0.6, 0.8) -- a keeper off to one side: aim a little less tight
		else
			zs = ballPos.Z >= gz and -1 or 1
		end
	end
	return Vector3.new(attack.pos.X, ballPos.Y, gz + zs * half * ratio), attack
end

return World

end

__mods["game/net"] = function()
-- Net: one __namecall hook for the whole script. Modules register a handler for a remote's name; the handler gets the packed arguments and may return a
-- replacement packed argument table, or nil to leave the call alone. Only FireServer / InvokeServer are looked at.
local Net = { handlers = {}, hooked = false, Error = nil }
local oldNC

local function nc(self, ...)
	local m = getnamecallmethod()
	if (m == "FireServer" or m == "InvokeServer") and typeof(self) == "Instance" then
		local n = self.Name
		for key, h in pairs(Net.handlers) do
			if n:find(key, 1, true) and not (key == "KickPlan" and n:find("Relay", 1, true)) then
				local packed = table.pack(...)
				local ok, res = pcall(h, packed, self)
				if ok and res then return oldNC(self, table.unpack(res, 1, res.n or packed.n)) end
				break
			end
		end
	end
	return oldNC(self, ...)
end

function Net.On(key, fn) Net.handlers[key] = fn end
function Net.Off(key) Net.handlers[key] = nil end

function Net.Start()
	if Net.hooked then return true end
	if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then Net.Error = "executor has no hookmetamethod"; return false end
	local ok, err = pcall(function() oldNC = hookmetamethod(game, "__namecall", newcclosure and newcclosure(nc) or nc) end)
	Net.hooked = ok
	if not ok then Net.Error = tostring(err) end
	return ok
end

function Net.Destroy() Net.handlers = {} end

return Net

end

__mods["game/rules"] = function()
-- Rules: the game's own rule tables (shared by its scripts and ours). Changing a number here changes what the game's client scripts do; each tweak is restored on switch-off.
--   Kick.Rules.Miss        random miss on kicks (set to 0 = perfect accuracy)
--   Dribble.Rules.Pickup   how far the ball can be taken / kept from (widened = sticky ball)
local RS = game:GetService("ReplicatedStorage")

local Rules = { Accurate = false, Sticky = false, StickyMult = 1.6, Info = "ready" }
local saved = {}

local function load(path)
	local ok, t = pcall(function()
		local m = RS
		for _, part in ipairs(path) do m = m:WaitForChild(part, 3) end
		return require(m)
	end)
	return ok and type(t) == "table" and t or nil
end

function Rules.SetAccurate(on)
	Rules.Accurate = on
	local R = load({ "Shared", "Game", "Kick", "Rules" })
	local miss = R and R.Miss
	if type(miss) ~= "table" then Rules.Info = "kick rules not found"; return false end
	pcall(function()
		if on then
			saved.miss = saved.miss or { Scale = miss.Scale, WeakFoot = miss.WeakFoot, Across = miss.Across }
			miss.Scale = 0; miss.WeakFoot = 1; miss.Across = 0
		elseif saved.miss then
			miss.Scale, miss.WeakFoot, miss.Across = saved.miss.Scale, saved.miss.WeakFoot, saved.miss.Across
		end
	end)
	return true
end

local PICK = { "FootReach", "BodyReach", "CushionReach", "MaxCarry", "KeepOut" }
function Rules.SetSticky(on, mult)
	Rules.Sticky = on
	if mult then Rules.StickyMult = mult end
	local R = load({ "Shared", "Game", "Dribble", "Rules" })
	local pickup = R and R.Pickup
	if type(pickup) ~= "table" then Rules.Info = "dribble rules not found"; return false end
	pcall(function()
		saved.pick = saved.pick or {}
		for _, k in ipairs(PICK) do
			if type(pickup[k]) == "number" then
				if saved.pick[k] == nil then saved.pick[k] = pickup[k] end
				pickup[k] = on and saved.pick[k] * Rules.StickyMult or saved.pick[k]
			end
		end
	end)
	return true
end

function Rules.Destroy()
	if Rules.Accurate then Rules.SetAccurate(false) end
	if Rules.Sticky then Rules.SetSticky(false) end
end

return Rules

end

__mods["game/speed"] = function()
-- Speed: the game moves your player from ReplicatedStorage.Shared.Game.MannequinAnimation.Tuning.Speed (Walk 8, Jog 19, Sprint 31 ...): its own movement script writes
-- BaseMoveSpeed from those numbers every frame. Scaling the numbers in that table is the clean way to change your speed. If the table cannot be loaded, the
-- ControllerManager's BaseMoveSpeed is scaled instead.
local RS = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local World = __import("game/world")

local Speed = { Mult = 1, Info = "off" }
local KEYS = { "Walk", "Jog", "Sprint", "SideStep", "BackStep", "SideStepSprint", "BackStepSprint", "Strafe", "StrafeBack", "SideSprint", "BackSprint" }
local orig, tuning
local conn, lastSet = nil, setmetatable({}, { __mode = "k" })

local function load()
	if tuning then return tuning end
	local ok, t = pcall(function()
		local m = RS
		for _, p in ipairs({ "Shared", "Game", "MannequinAnimation", "Tuning" }) do m = m:WaitForChild(p, 3) end
		return require(m)
	end)
	if ok and type(t) == "table" and type(t.Speed) == "table" then tuning = t.Speed end
	return tuning
end

function Speed.Set(mult)
	Speed.Mult = mult
	local sp = load()
	if sp then
		orig = orig or {}
		for _, k in ipairs(KEYS) do
			if type(sp[k]) == "number" then
				if orig[k] == nil then orig[k] = sp[k] end
				sp[k] = orig[k] * mult
			end
		end
		Speed.Info = ("x%.2f (Tuning.Speed)"):format(mult)
		if conn then conn:Disconnect(); conn = nil end
	else
		-- fallback: boost BaseMoveSpeed after the game wrote it
		Speed.Info = ("x%.2f (controller)"):format(mult)
		if not conn then
			conn = RunService.PreSimulation:Connect(function()
				local me = World.me()
				if not (me and me.cm) or Speed.Mult == 1 then return end
				local cur, mine = me.cm.BaseMoveSpeed, lastSet[me.cm]
				if mine == nil or math.abs(cur - mine) > 1e-3 then
					lastSet[me.cm] = cur * Speed.Mult
					me.cm.BaseMoveSpeed = cur * Speed.Mult
				end
			end)
		end
	end
end

function Speed.Destroy()
	Speed.Set(1)
	if conn then conn:Disconnect(); conn = nil end
end

return Speed

end

__mods["game/kick"] = function()
-- Kick: assist for YOUR shots. You still aim, charge and kick yourself; this changes what is sent to the server.
--  The game computes a kick locally and sends KickPlan (the plan: dir, power, family ...) and then DribbleRelease (ball position, launch velocity, spin, family).
--  * Aim:        the horizontal direction is turned to a point inside the opponent's goal (away from the keeper). KickPlan.dir is replaced and the release velocity /
--                spin are rotated by the same angle, so the two still agree with each other.
--  * Super shot: the kick is sent as the strongest family ("Power") with the highest speed the server allows, along the FLATTEST path that still reaches the goal
--                (solved with the game's own drag and gravity), so the ball arrives as fast as possible. The server clamps the speed per kick family (seen in the log:
--                Backheel ~75, RunOutside ~117, Laced ~138, Power ~156); the clamp is learned from the server's reply, so every shot asks for a bit more until it is found.
local RS = game:GetService("ReplicatedStorage")
local World = __import("game/world")
local Net = __import("game/net")
local Log = __import("game/log")

local Kick = {
	Aim = false, Super = true, Family = "Power", MaxAngle = 55, AllKicks = true, MaxDist = 400, Corner = "Far from keeper",
	Shots = 0, Notify = nil, Info = "off",
}
Kick.Corners = { "Far from keeper", "Left post", "Right post", "Centre" }
Kick.Families = { "Power", "Laced", "Finesse" }
Kick.Cap = {}      -- family -> highest speed the server has accepted so far
local CAP_GUESS = 150

local lastAim = { rot = nil, dir = nil, dist = 0, y = 1.9, t = -99 }
local lastSuper = { t = -99, family = nil }
local rejectConn, flightConn

-- height of the ball when it has travelled `dist` horizontally, launched at speed s and angle ang (quadratic drag, gravity g); -1e9 if it lands before
local function heightAt(s, ang, dist, y0, g, k)
	local vx, vy = s * math.cos(ang), s * math.sin(ang)
	local x, y = 0, y0
	local dt = 1 / 100
	for _ = 1, 2000 do
		local sp = math.sqrt(vx * vx + vy * vy)
		vx = vx - k * sp * vx * dt
		vy = vy - (g + k * sp * vy) * dt
		local nx, ny = x + vx * dt, y + vy * dt
		if nx >= dist then return y + (ny - y) * ((dist - x) / math.max(nx - x, 1e-6)) end
		if ny < y0 - 0.3 and vy < 0 then return -1e9 end
		x, y = nx, ny
	end
	return -1e9
end

-- the flattest launch angle (radians) that still has the ball at height yt when it reaches dist, at a fixed speed
function Kick.SolveAngle(dist, speed, y0, yt, g, k, maxDeg)
	local lo, hi = math.rad(1), math.rad(maxDeg)
	if heightAt(speed, hi, dist, y0, g, k) < yt then return hi end -- not reachable: steepest allowed
	if heightAt(speed, lo, dist, y0, g, k) >= yt then return lo end -- reachable flat
	for _ = 1, 26 do
		local mid = (lo + hi) / 2
		if heightAt(speed, mid, dist, y0, g, k) >= yt then hi = mid else lo = mid end
	end
	return hi
end

local function onPlan(args)
	local plan = args[1]
	if type(plan) ~= "table" or typeof(plan.dir) ~= "Vector3" or typeof(plan.ball) ~= "Vector3" then return nil end
	local me = World.me()
	if not me then return nil end
	local target = World.shotTarget(me.team, plan.ball, Kick.Corner)
	if not target then Log.add("KickPlan: no goal found"); return nil end
	local toGoal = World.horiz(target - plan.ball)
	if toGoal.Magnitude < 1 or toGoal.Magnitude > Kick.MaxDist then return nil end
	local oldDir = World.horiz(plan.dir)
	if oldDir.Magnitude < 0.01 then return nil end
	local newDir, oldUnit = toGoal.Unit, oldDir.Unit
	if not Kick.AllKicks then
		local ang = math.deg(math.acos(math.clamp(oldUnit:Dot(newDir), -1, 1)))
		if ang > 75 then return nil end -- "shots only": a kick that points away from the goal is a pass, leave it
	end
	local np = table.clone(plan)
	np.dir = newDir
	if Kick.Super then np.family = Kick.Family; np.power = 1 end
	lastAim.rot = CFrame.lookAt(Vector3.zero, newDir) * CFrame.lookAt(Vector3.zero, oldUnit):Inverse()
	lastAim.dist = toGoal.Magnitude
	lastAim.dir = newDir
	lastAim.y = plan.ball.Y
	lastAim.t = os.clock()
	Kick.Shots = Kick.Shots + 1
	Log.add(("KickPlan aimed at goal: %d studs, family %s -> %s, power %s"):format(math.floor(toGoal.Magnitude), tostring(plan.family), Kick.Super and Kick.Family or "unchanged", tostring(plan.power)))
	local out = table.clone(args)
	out[1] = np
	return out
end

local function onRelease(args)
	-- DribbleRelease(pid, kind, ballPos, vel, t, nil, spin, family)
	if not lastAim.rot or os.clock() - lastAim.t > 1.5 then return nil end
	local vel = args[4]
	if typeof(vel) ~= "Vector3" then return nil end
	local out = table.clone(args)
	local v = lastAim.rot * vel
	local note
	if Kick.Super and lastAim.dir then
		local ball = World.ball()
		local g = (ball and tonumber(ball:GetAttribute("Gravity"))) or 46
		local air = (ball and tonumber(ball:GetAttribute("AirDrag"))) or 1
		local k = 0.024366064765727467 * air * 0.213
		local cap = Kick.Cap[Kick.Family] or CAP_GUESS
		local ask = cap * 1.12 -- a little above what has been accepted so far; the server clamps and the reply tells the real limit
		local y0 = lastAim.y
		local ang = Kick.SolveAngle(lastAim.dist, cap, y0, y0 + 0.9, g, k, Kick.MaxAngle)
		v = lastAim.dir * (ask * math.cos(ang)) + Vector3.new(0, ask * math.sin(ang), 0)
		out[8] = Kick.Family
		out[7] = Vector3.zero
		lastSuper.t, lastSuper.family = os.clock(), Kick.Family
		note = ("SUPER SHOT  -  %d st  -  %d studs/s"):format(math.floor(lastAim.dist), math.floor(ask))
		Log.add(("SUPER: %d studs, asked %.0f studs/s at %.1f deg (known cap %.0f, family %s)"):format(math.floor(lastAim.dist), ask, math.deg(ang), cap, Kick.Family))
	else
		if typeof(args[7]) == "Vector3" then out[7] = lastAim.rot * args[7] end
		note = ("Shot at goal  -  %d st"):format(math.floor(lastAim.dist))
		Log.add("DribbleRelease rotated")
	end
	out[4] = v
	lastAim.rot = nil
	if Kick.Notify then Kick.Notify(note) end
	return out
end

-- the server tells you when it refuses a release; log it
local function watchRejects()
	if rejectConn then return end
	pcall(function()
		for _, d in ipairs(RS:GetDescendants()) do
			if d:IsA("RemoteEvent") and d.Name:find("DribbleReject", 1, true) then
				rejectConn = d.OnClientEvent:Connect(function(...)
					Log.add("SERVER REJECTED a dribble / kick call: " .. tostring((...)))
				end)
				break
			end
		end
	end)
end

-- what the SERVER did with the kick: its KickFlight attribute holds the launch velocity it accepted. That is how the speed cap per family is learned.
-- format: version | id | t | pos x y z | vel x y z | spin x y z | player | family
local function watchFlight()
	local ball = World.ball()
	if not ball or flightConn then return end
	flightConn = ball:GetAttributeChangedSignal("KickFlight"):Connect(function()
		local raw = tostring(ball:GetAttribute("KickFlight"))
		Log.add("server KickFlight: " .. raw:sub(1, 140))
		if os.clock() - lastSuper.t < 3 then
			local f = string.split(raw, "|")
			local vx, vy, vz = tonumber(f[7]), tonumber(f[8]), tonumber(f[9])
			local fam = f[14]
			if vx and vy and vz and fam == lastSuper.family then
				local sp = math.sqrt(vx * vx + vy * vy + vz * vz)
				local prev = Kick.Cap[fam] or 0
				if sp > prev or sp < prev * 0.9 then
					Kick.Cap[fam] = sp
					Log.add(("learned: %s accepted up to %.0f studs/s"):format(fam, sp))
					if Kick.Notify then Kick.Notify(("Server accepted %.0f studs/s"):format(sp)) end
				end
				lastSuper.t = -99
			end
		end
	end)
end

function Kick.SetAim(on)
	Kick.Aim = on
	if on then
		if not Net.Start() then Kick.Info = Net.Error or "hook failed"; Log.add("hook failed: " .. tostring(Net.Error)); return false end
		Net.On("KickPlan", onPlan)
		Net.On("DribbleRelease", onRelease)
		watchRejects()
		watchFlight()
		Kick.Info = "aiming"
	else
		Net.Off("KickPlan"); Net.Off("DribbleRelease")
		Kick.Info = "off"
	end
	return true
end

function Kick.Destroy()
	Kick.SetAim(false)
	if rejectConn then rejectConn:Disconnect(); rejectConn = nil end
	if flightConn then flightConn:Disconnect(); flightConn = nil end
end

return Kick

end

__mods["game/fun"] = function()
-- Fun: silly mechanics for your own player. All of it only drives your own ControllerManager (FacingDirection) / Root, before every physics step.
--   Spinbot    your player spins on the spot while you play (the kick still goes where the aim assist sends it)
--   Moonwalk   you face away from where you run
--   Sideways   you run sideways (face 90 degrees off your direction)
--   Jitter     your player shakes: other people see you vibrate around your real spot
--   Ball magnet  teleport behind a loose ball that is within range (blatant)
local RunService = game:GetService("RunService")
local World = __import("game/world")
local Log = __import("game/log")

local Fun = {
	RainbowBall = false, AimLine = false, Corner = "Far from keeper",
	Spin = false, SpinRate = 900, Moonwalk = false, Sideways = false, Jitter = false, JitterSize = 1.6, Magnet = false, MagnetRange = 60,
}

local conn
local spinAngle, lastMagnet, jitterFlip = 0, -99, 1

local line, hue = nil, 0
local function ensureLine()
	if line and line.Parent then return line end
	line = Instance.new("Part")
	line.Name = tostring(math.random(1e6, 9e6)); line.Anchored = true; line.CanCollide = false; line.CanQuery = false; line.CanTouch = false
	line.Material = Enum.Material.Neon; line.Color = Color3.fromRGB(80, 220, 140); line.Transparency = 0.35
	line.Size = Vector3.new(0.25, 0.25, 1); line.Parent = workspace
	return line
end
local function killLine()
	if line then pcall(function() line:Destroy() end); line = nil end
end

local function visuals(dt)
	local ball = World.ball()
	if Fun.RainbowBall and ball then
		hue = (hue + dt * 0.6) % 1
		pcall(function() ball.Color = Color3.fromHSV(hue, 0.85, 1) end)
	end
	if Fun.AimLine and ball then
		local me = World.me()
		local target = me and World.shotTarget(me.team, ball.Position, Fun.Corner)
		if target and (me.root.Position - ball.Position).Magnitude < 40 then
			local a, b = ball.Position, target
			local l = ensureLine()
			local len = (b - a).Magnitude
			l.Size = Vector3.new(0.25, 0.25, math.max(len, 0.1))
			l.CFrame = CFrame.lookAt(a, b) * CFrame.new(0, 0, -len / 2)
		else
			killLine()
		end
	elseif line then
		killLine()
	end
end

local function step(dt)
	visuals(dt)
	if not (Fun.Spin or Fun.Moonwalk or Fun.Sideways or Fun.Jitter or Fun.Magnet) then return end
	local me = World.me()
	if not me or not me.cm then return end
	if me.state ~= nil and me.state ~= "Animated" then return end
	local cm, root = me.cm, me.root
	local move = World.horiz(cm.MovingDirection)

	-- facing games (one wins, in this order)
	if Fun.Spin then
		spinAngle = (spinAngle + math.rad(Fun.SpinRate) * dt) % (math.pi * 2)
		pcall(function() cm.FacingDirection = Vector3.new(math.cos(spinAngle), 0, math.sin(spinAngle)) end)
	elseif move.Magnitude > 0.1 then
		if Fun.Moonwalk then
			pcall(function() cm.FacingDirection = -move.Unit end)
		elseif Fun.Sideways then
			local d = move.Unit
			pcall(function() cm.FacingDirection = Vector3.new(-d.Z, 0, d.X) end)
		end
	end

	-- jitter: tiny sideways offsets every frame, alternating, so everybody else sees a vibrating player
	if Fun.Jitter then
		jitterFlip = -jitterFlip
		local side = root.CFrame.RightVector
		pcall(function() root.CFrame = root.CFrame + side * (Fun.JitterSize * 0.12 * jitterFlip) end)
	end

	-- ball magnet
	if Fun.Magnet and os.clock() - lastMagnet > 0.6 and me.role ~= "Goalkeeper" then
		local ball = World.ball()
		if ball and World.possession(ball, me) == "free" then
			local pos, bp = root.Position, ball.Position
			local d = World.horiz(bp - pos).Magnitude
			if d > 6 and d <= Fun.MagnetRange then
				lastMagnet = os.clock()
				local target = World.shotTarget(me.team, bp, "Centre")
				local back = target and World.horiz(target - bp).Unit * -2.2 or Vector3.zero
				local np = Vector3.new(bp.X + back.X, pos.Y, bp.Z + back.Z)
				pcall(function()
					root.CFrame = CFrame.new(np, np - (back.Magnitude > 0 and back or Vector3.new(0, 0, 1)))
					root.AssemblyLinearVelocity = Vector3.zero
				end)
				Log.add(("magnet: teleported to the ball (%d studs)"):format(math.floor(d)))
			end
		end
	end
end

function Fun.Start()
	if conn then return end
	conn = RunService.PreSimulation:Connect(function(dt) pcall(step, dt) end)
end

function Fun.Destroy()
	if conn then conn:Disconnect(); conn = nil end
	killLine()
	Fun.Spin, Fun.Moonwalk, Fun.Sideways, Fun.Jitter, Fun.Magnet, Fun.RainbowBall, Fun.AimLine = false, false, false, false, false, false, false
end

return Fun

end

__mods["game/keeper"] = function()
-- Keeper: assist for when YOU are the goalkeeper (Role == "Goalkeeper"). Does nothing while you play outfield.
--  * Goal-line lock: you slide to the best spot between the ball and the middle of the goal (or to the exact spot a shot will cross the line), staying inside the goal width and
--    a little off the line. You still move yourself; this only adds a correction every frame, faster than a normal run.
--  * Auto dive: the ball's flight is predicted with the game's drag + gravity; when it is going to cross the goal line inside the posts, the right dive key is pressed at the
--    right time (Q / E mid, Z / C low, jump + Q / E high, X smother). The game still does the dive itself, so the server sees a normal dive.
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local World = __import("game/world")
local Log = __import("game/log")
local lp = Players.LocalPlayer

local Keeper = {
	Enabled = false, Dive = true, Lock = true, FaceBall = true,
	Reaction = 0.8,    -- seconds before the ball crosses the line at which the dive is pressed
	Out = 7,           -- how far off the goal line you stand when the ball is far (studs)
	Speed = 42,        -- slide speed of the goal-line lock (studs/s)
	MinDive = 2.2,     -- a shot this close to you is not dived at (you are already there)
	Smother = true, Rush = true, RushRange = 30, Saves = 0, Info = "off",
}

local conn
local vel, lastPos = Vector3.zero, nil
local lastDive, lastLog = -99, -99
local floorY, loggedGoal = nil, false
local flight, flightBall, flightConn

-- the server's own KickFlight record: exact start position and velocity of every kick, known the moment it happens
local function hookFlight(ball)
	if flightBall == ball then return end
	if flightConn then flightConn:Disconnect() end
	flightBall = ball
	flightConn = ball:GetAttributeChangedSignal("KickFlight"):Connect(function()
		local f = string.split(tostring(ball:GetAttribute("KickFlight")), "|")
		local px, py, pz, vx, vy, vz = tonumber(f[4]), tonumber(f[5]), tonumber(f[6]), tonumber(f[7]), tonumber(f[8]), tonumber(f[9])
		if px and pz and vx and vz then flight = { p = Vector3.new(px, py, pz), v = Vector3.new(vx, vy or 0, vz), t0 = os.clock() } end
	end)
end
local actions = {}

local function horiz(v) return Vector3.new(v.X, 0, v.Z) end

-- InputActions are created by the game's input layer under PlayerScripts (one InputContext per group); found by name
local function action(name)
	local a = actions[name]
	if a and a.Parent then return a end
	local ps = lp:FindFirstChild("PlayerScripts")
	if not ps then return nil end
	for _, ctx in ipairs(ps:GetChildren()) do
		if ctx:IsA("InputContext") then
			local x = ctx:FindFirstChild(name)
			if x and x:IsA("InputAction") then actions[name] = x; return x end
		end
	end
	return nil
end

local function press(name, hold)
	local a = action(name)
	if not a then Log.add("keeper: input action not found: " .. name); return false end
	local ok = pcall(function() a:Fire(true) end)
	task.delay(hold or 0.12, function() pcall(function() a:Fire(false) end) end)
	return ok
end

-- ball velocity: the physics velocity when it has one, otherwise the movement between frames
local function trackBall(ball, dt)
	local p = ball.Position
	local v = ball.AssemblyLinearVelocity
	if v.Magnitude < 3 and lastPos and dt > 0 then
		local est = (p - lastPos) / dt
		if est.Magnitude < 500 then v = vel:Lerp(est, 0.6) end
	end
	lastPos = p
	vel = v
	return p, v
end

-- where and when the ball crosses the goal line plane x = goalX (outward = sign of the goal's side). nil if it never gets there within 3 s.
local function predict(p, v, goalX, outward, g, k, floor)
	local x, y, z = p.X, p.Y, p.Z
	local vx, vy, vz = v.X, v.Y, v.Z
	local dt = 1 / 60
	for i = 1, 180 do
		local sp = math.sqrt(vx * vx + vy * vy + vz * vz)
		vx = vx - k * sp * vx * dt
		vy = vy - (g + k * sp * vy) * dt
		vz = vz - k * sp * vz * dt
		local nx = x + vx * dt
		if (nx - goalX) * outward >= 0 then
			local f = ((goalX - x) / math.max(nx - x, 1e-6))
			f = math.clamp(f, 0, 1)
			return i * dt, y + vy * dt * f, z + vz * dt * f
		end
		x, y, z = nx, y + vy * dt, z + vz * dt
		if y < floor then -- ground: the ball bounces a little, then rolls
			y = floor
			vy = vy < -6 and -vy * 0.5 or 0
		end
	end
	return nil
end

local function step(dt)
	if not Keeper.Enabled then return end
	local me = World.me()
	if not me or me.role ~= "Goalkeeper" then Keeper.Info = "not in goal"; return end
	local ball = World.ball()
	local goal = World.ownGoal(me.team)
	if not (ball and goal) then Keeper.Info = "no goal found"; return end
	Keeper.Info = "guarding"
	if not loggedGoal then
		loggedGoal = true
		Log.add(("keeper: own goal at (%.0f, %.0f) size (%.0f, %.0f, %.0f), outward %d, half width used %.1f"):format(goal.pos.X, goal.pos.Z, goal.size.X, goal.size.Y, goal.size.Z, goal.outward, math.max(goal.size.Z, goal.size.X) / 2))
	end

	hookFlight(ball)
	local bp, bv = trackBall(ball, dt)
	-- ground level for the ball = the lowest it has been seen (it rests there); forgotten slowly in case the pitch differs
	floorY = floorY and math.min(floorY + dt * 0.05, bp.Y) or bp.Y
	local root = me.root
	local half = math.max(goal.size.Z, goal.size.X) / 2
	local gx, gz = goal.pos.X, goal.pos.Z
	local outward = goal.outward -- +1 when the goal is on the +X end
	local g = tonumber(ball:GetAttribute("Gravity")) or 46
	local air = tonumber(ball:GetAttribute("AirDrag")) or 1
	local k = 0.024366064765727467 * air * 0.213

	-- is a shot on its way?
	local lineX = gx - outward * math.max(goal.size.X / 2 - 1, 0) -- the front of the goal, where the ball counts as in
	local possession = World.possession(ball, me)
	local threat
	local p0, v0, elapsed = bp, bv, 0
	if flight and possession == "free" and os.clock() - flight.t0 < 3 then p0, v0, elapsed = flight.p, flight.v, os.clock() - flight.t0 end
	if v0.X * outward > 16 then
		local t, y, z = predict(p0, v0, lineX, outward, g, k, floorY)
		if t then
			t = t - elapsed
			if t > -0.08 and math.abs(z - gz) <= half + 4 and y - root.Position.Y < 12 then threat = { t = math.max(t, 0), y = y, z = z } end
		end
	end

	local hasBall = possession == "me"
	local busy = me.state ~= nil and me.state ~= "Animated"

	-- goal-line lock
	if Keeper.Lock and not busy and not hasBall then
		local inward = -outward
		local tz, depth
		local d2goal = horiz(bp - Vector3.new(gx, 0, gz)).Magnitude
		local rush = Keeper.Rush and possession == "other" and not threat and d2goal < Keeper.RushRange
		if rush then
			-- somebody dribbles at you: come off the line to the ball, on the line ball -> goal centre, to shrink the angle
			local dirv = horiz(Vector3.new(gx, 0, gz) - bp)
			dirv = dirv.Magnitude > 0.5 and dirv.Unit or Vector3.new(inward, 0, 0)
			local want = bp + dirv * 4.5
			tz = math.clamp(want.Z, gz - (half - 1.5), gz + (half - 1.5))
			depth = math.clamp((want.X - lineX) * inward, 1.5, Keeper.RushRange)
			if horiz(bp - root.Position).Magnitude < 9 and os.clock() - lastDive > 1.6 then
				lastDive = os.clock()
				press("Smother")
				Log.add(("keeper: rush smother, ball %.1f studs away"):format(horiz(bp - root.Position).Magnitude))
			end
		elseif threat then
			tz = math.clamp(threat.z, gz - (half - 1), gz + (half - 1))
			depth = 2.5
		else
			local centre = Vector3.new(gx, root.Position.Y, gz)
			local dirv = horiz(bp - centre)
			if dirv.Magnitude < 1 then dirv = Vector3.new(inward, 0, 0) end
			dirv = dirv.Unit
			local want = Vector3.new(lineX, 0, gz) + dirv * math.min(Keeper.Out, (horiz(bp - centre)).Magnitude * 0.5)
			tz = math.clamp(want.Z, gz - (half - 1.5), gz + (half - 1.5))
			depth = math.clamp((want.X - lineX) * inward, 1.5, Keeper.Out + 2)
		end
		local target = Vector3.new(lineX + inward * depth, root.Position.Y, tz)
		local cur = root.Position
		local delta = horiz(target - cur)
		local mag = delta.Magnitude
		if mag > 0.25 then
			local sp = Keeper.Speed * ((threat or rush) and 1.8 or 1)
			local np = cur + delta.Unit * math.min(mag, sp * dt)
			local face = root.CFrame - root.CFrame.Position
			if Keeper.FaceBall then
				local look = horiz(bp - np)
				if look.Magnitude > 0.5 then face = CFrame.lookAt(Vector3.zero, look) end
			end
			pcall(function() root.CFrame = CFrame.new(np) * face end)
		end
	end

	-- auto dive
	if Keeper.Dive and threat and not busy and not hasBall and threat.t <= Keeper.Reaction and os.clock() - lastDive > 1.1 then
		local cam = workspace.CurrentCamera
		local right = cam and horiz(cam.CFrame.RightVector)
		if right and right.Magnitude > 0.05 then
			right = right.Unit
			local cross = Vector3.new(lineX, threat.y, threat.z)
			local rel = horiz(cross - root.Position)
			local lat = rel:Dot(right)
			local high = threat.y - root.Position.Y > 3.4
			local low = threat.y - root.Position.Y < 0.4
			lastDive = os.clock()
			if math.abs(lat) < Keeper.MinDive then
				if Keeper.Smother and not high and rel.Magnitude < 12 and threat.t <= Keeper.Reaction * 0.6 then
					press("Smother")
					Log.add(("keeper: smother (ball %.1f s away, %.1f off-centre)"):format(threat.t, lat))
				else
					lastDive = -99
				end
			else
				local side = lat > 0 and "Right" or "Left"
				Keeper.Saves = Keeper.Saves + 1
				if high then
					press("Jump", 0.35)
					task.delay(0.04, function() press("Dive" .. side) end)
				elseif low then
					press("LowDive" .. side)
				else
					press("Dive" .. side)
				end
				Log.add(("keeper: dive %s (%s), ball crosses in %.2fs, %.1f studs away, height %.1f"):format(side, high and "high" or low and "low" or "mid", threat.t, lat, threat.y - root.Position.Y))
			end
		end
	end

	if threat and os.clock() - lastLog > 1 then
		lastLog = os.clock()
		Log.add(("keeper: shot coming, crosses in %.2fs at z offset %.1f, height %.1f"):format(threat.t, threat.z - gz, threat.y - root.Position.Y))
	end
end

function Keeper.Start()
	if conn then return end
	conn = RunService.PreSimulation:Connect(function(dt) pcall(step, dt) end)
end

function Keeper.Set(on)
	Keeper.Enabled = on
	if not on then Keeper.Info = "off"; vel, lastPos = Vector3.zero, nil end
end

function Keeper.Destroy()
	if flightConn then flightConn:Disconnect(); flightConn = nil end
	if conn then conn:Disconnect(); conn = nil end
	Keeper.Enabled = false
end

return Keeper

end

-- main
-- Ragdoll Soccer: entry point. One window, one module (Ronaldini Banini) with everything inside its settings, and a small Settings tab.
-- Ronaldini is an ASSISTER: you move, aim, charge and kick yourself; it fixes the shot (goal, power, accuracy), keeps the ball with you and adds silly mechanics.
local UIS = game:GetService("UserInputService")
local UI = __import("lib/ui")
local Sfx = __import("lib/sfx")
local Config = __import("lib/config")
local Log = __import("game/log")
local Net = __import("game/net")
local Rules = __import("game/rules")
local Speed = __import("game/speed")
local Kick = __import("game/kick")
local Fun = __import("game/fun")
local Keeper = __import("game/keeper")

local env = getgenv and getgenv() or _G
local VERSION = tostring(env.RSVersion or "dev")
print("[RagdollSoccer] running " .. VERSION)

-- a second run replaces the first
if env.__RagdollSoccer then pcall(env.__RagdollSoccer) end

local win = UI.new({ Title = "Ragdoll Soccer", Subtitle = "v" .. VERSION })
local alive = true
Log.Start()
Log.add("loaded v" .. VERSION)
Kick.Notify = function(msg) win:Notify(msg, 2) end

-- RONALDINI ---------------------------------------------------------------------------------------------------------------
local tMain = win:Tab("Ronaldini", { Section = "Play", Icon = 13 })
local speedMult, sticky, accurate = 1.0, true, true
local funState = { Spin = false, Moonwalk = false, Sideways = false, Jitter = false, Magnet = false, RainbowBall = false, AimLine = false }
local mBan

local function applyFun(on)
	for k, v in pairs(funState) do Fun[k] = on and v end
end

local function apply(on)
	Kick.SetAim(on)
	Rules.SetAccurate(on and accurate)
	Rules.SetSticky(on and sticky)
	Speed.Set(on and speedMult or 1)
	applyFun(on)
	win:Notify(on and "Ronaldini Banini ON" or "Ronaldini Banini off", 2)
	Log.add(on and "Ronaldini ON" or "Ronaldini off")
end

mBan = tMain:Module({ Name = "Ronaldini Banini", Default = false, Callback = apply })
local key = mBan:Keybind({ Name = "Toggle key", Default = Enum.KeyCode.Z })

mBan:Section("Your shots")
mBan:Choice({ Name = "Where in the goal", Options = Kick.Corners, Default = Kick.Corner, Callback = function(v) Kick.Corner = v; Fun.Corner = v end })
mBan:Choice({ Name = "Applies to", Options = { "All kicks", "Shots only" }, Default = "All kicks", Callback = function(v) Kick.AllKicks = v == "All kicks" end })
mBan:Toggle({ Name = "SUPER SHOT: hardest kick, flattest path to the goal", Default = Kick.Super, Callback = function(v) Kick.Super = v end })
mBan:Choice({ Name = "Shot type", Options = Kick.Families, Default = Kick.Family, Callback = function(v) Kick.Family = v end })
mBan:Slider({ Name = "Highest launch angle", Min = 10, Max = 70, Step = 1, Default = Kick.MaxAngle, Suffix = " deg", Callback = function(v) Kick.MaxAngle = v end })
mBan:Slider({ Name = "Works up to", Min = 40, Max = 500, Step = 10, Default = Kick.MaxDist, Suffix = " st", Callback = function(v) Kick.MaxDist = v end })

mBan:Section("Ball")
mBan:Toggle({ Name = "Perfect accuracy", Default = true, Callback = function(v) accurate = v; if mBan:Get() then Rules.SetAccurate(v) end end })
mBan:Toggle({ Name = "Sticky ball (wider pickup reach)", Default = true, Callback = function(v) sticky = v; if mBan:Get() then Rules.SetSticky(v) end end })
mBan:Slider({ Name = "Sticky reach", Min = 1, Max = 3.5, Step = 0.1, Default = Rules.StickyMult, Suffix = "x", Callback = function(v) Rules.StickyMult = v; if mBan:Get() and sticky then Rules.SetSticky(true, v) end end })

mBan:Section("Speed")
mBan:Slider({ Name = "Speed multiplier", Min = 1, Max = 3, Step = 0.05, Default = speedMult, Suffix = "x", Callback = function(v) speedMult = v; if mBan:Get() then Speed.Set(v) end end })

mBan:Section("Funny")
local function fun(name, label)
	mBan:Toggle({ Name = label, Default = false, Callback = function(v) funState[name] = v; if mBan:Get() then Fun[name] = v end end })
end
mBan:Toggle({ Name = "Rainbow ball", Default = false, Callback = function(v) funState.RainbowBall = v; if mBan:Get() then Fun.RainbowBall = v end end })
mBan:Toggle({ Name = "Aim line (shows where the shot goes)", Default = false, Callback = function(v) funState.AimLine = v; if mBan:Get() then Fun.AimLine = v end end })
fun("Spin", "Spinbot")
mBan:Slider({ Name = "Spin speed", Min = 90, Max = 3000, Step = 30, Default = Fun.SpinRate, Suffix = " deg/s", Callback = function(v) Fun.SpinRate = v end })
fun("Moonwalk", "Moonwalk (face away from where you run)")
fun("Sideways", "Run sideways")
fun("Jitter", "Jitter (others see you vibrate)")
mBan:Slider({ Name = "Jitter size", Min = 0.5, Max = 6, Step = 0.1, Default = Fun.JitterSize, Suffix = " st", Callback = function(v) Fun.JitterSize = v end })
fun("Magnet", "Teleport to the loose ball (blatant)")
mBan:Slider({ Name = "Teleport range", Min = 15, Max = 200, Step = 5, Default = Fun.MagnetRange, Suffix = " st", Callback = function(v) Fun.MagnetRange = v end })

-- KEEPER -----------------------------------------------------------------------------------------------------------------------
local mKeep = tMain:Module({ Name = "Keeper Banini", Default = false, Callback = function(on)
	Keeper.Set(on)
	win:Notify(on and "Keeper Banini ON  -  works while you are the goalkeeper" or "Keeper Banini off", 2)
	Log.add(on and "Keeper ON" or "Keeper off")
end })
local keeperKey = mKeep:Keybind({ Name = "Toggle key", Default = Enum.KeyCode.V })
mKeep:Section("Goal line")
mKeep:Toggle({ Name = "Goal-line lock (slides you to the best spot)", Default = true, Callback = function(v) Keeper.Lock = v end })
mKeep:Slider({ Name = "Stand off the line", Min = 2, Max = 16, Step = 0.5, Default = Keeper.Out, Suffix = " st", Callback = function(v) Keeper.Out = v end })
mKeep:Slider({ Name = "Slide speed", Min = 15, Max = 120, Step = 1, Default = Keeper.Speed, Suffix = " st/s", Callback = function(v) Keeper.Speed = v end })
mKeep:Toggle({ Name = "Face the ball", Default = true, Callback = function(v) Keeper.FaceBall = v end })
mKeep:Toggle({ Name = "Rush out at dribblers (shrinks the angle, smothers)", Default = true, Callback = function(v) Keeper.Rush = v end })
mKeep:Slider({ Name = "Rush when the ball is within", Min = 10, Max = 60, Step = 1, Default = Keeper.RushRange, Suffix = " st", Callback = function(v) Keeper.RushRange = v end })
mKeep:Section("Dives")
mKeep:Toggle({ Name = "Auto dive at shots", Default = true, Callback = function(v) Keeper.Dive = v end })
mKeep:Slider({ Name = "Dive this early", Min = 0.2, Max = 1.2, Step = 0.05, Default = Keeper.Reaction, Suffix = " s", Callback = function(v) Keeper.Reaction = v end })
mKeep:Toggle({ Name = "Smother shots straight at you", Default = true, Callback = function(v) Keeper.Smother = v end })

-- SETTINGS ---------------------------------------------------------------------------------------------------------------------
local tSet = win:Tab("Settings", { Section = "Client", Icon = 9 })
tSet:Section("Window")
tSet:Slider({ Name = "UI scale", Min = 0.7, Max = 1.4, Step = 0.05, Default = 1, Callback = function(v) win:SetScale(v) end })
tSet:Slider({ Name = "Blur behind the window", Min = 0, Max = 30, Step = 1, Default = 0, Callback = function(v) win:SetBlur(v) end })
tSet:Toggle({ Name = "Interface sounds", Default = true, Callback = function(v) Sfx.Enabled = v end })
tSet:Section("Theme")
local THEMES = {
	{ "Mono", UI.Palette().accent, UI.Palette().bg }, { "Aurora", Color3.fromRGB(139, 92, 246), Color3.fromRGB(11, 10, 22) },
	{ "Pitch", Color3.fromRGB(46, 204, 120), Color3.fromRGB(10, 18, 14) }, { "Ocean", Color3.fromRGB(52, 152, 219), Color3.fromRGB(10, 16, 26) },
	{ "Crimson", Color3.fromRGB(231, 76, 60), Color3.fromRGB(20, 11, 11) },
}
local themeNames = {}
for _, t in ipairs(THEMES) do themeNames[#themeNames + 1] = t[1] end
tSet:Choice({ Name = "Theme", Options = themeNames, Default = "Mono", Callback = function(v)
	for _, t in ipairs(THEMES) do
		if t[1] == v then win:ApplyPalette(UI.Palette(t[2], t[3])) end
	end
end })
tSet:Section("About")
tSet:Label({ Name = "Version", Value = VERSION })
tSet:Label({ Name = "Hide / show window", Value = "Right Shift" })
tSet:Label({ Name = "Event log", Value = "RagdollSoccer/log.txt" })

-- unload / autosave ----------------------------------------------------------------------------------------------------------------
local function save() if Config.Available then pcall(function() Config.Write("default", { v = 1, flags = win:GetConfig() }) end) end end
local function unload()
	pcall(save)
	alive = false
	Fun.Destroy(); Keeper.Destroy(); Kick.Destroy(); Rules.Destroy(); Speed.Destroy(); Net.Destroy(); Log.Destroy()
	win:Destroy()
	env.__RagdollSoccer = nil
end
tSet:Button({ Name = "Unload", NoSave = true, Callback = unload })
env.__RagdollSoccer = unload

Fun.Start()
Keeper.Start()

if Config.Available then
	local data = Config.Read("default")
	if data and data.flags then win:ApplyConfig(data.flags) end
	task.spawn(function()
		while alive do
			task.wait(5)
			save()
		end
	end)
end

table.insert(win.conns, UIS.InputBegan:Connect(function(i)
	if i.KeyCode == Enum.KeyCode.RightShift then win:Toggle(); return end
	if i.UserInputType ~= Enum.UserInputType.Keyboard or UIS:GetFocusedTextBox() or key:IsListening() or keeperKey:IsListening() then return end
	if key:Get() == i.KeyCode then mBan:Set(not mBan:Get()) end
	if keeperKey:Get() == i.KeyCode then mKeep:Set(not mKeep:Get()) end
end))

win:Notify("Ragdoll Soccer loaded  -  press Z to turn Ronaldini on", 4, "success")
